using System;
using System.Collections.Generic;
using System.Text;

namespace DotNetOutdated.Core.Services;

/// <summary>
/// Statically evaluates the subset of MSBuild condition syntax that appears in version-property definitions:
/// <c>==</c> / <c>!=</c> string comparisons, <c>and</c>, <c>or</c>, <c>!</c>, parentheses, boolean literals and
/// <c>Exists('path')</c>. Anything else, or any value that can't be expanded statically, makes the result
/// <see langword="null"/> (unknown) rather than a guess.
/// </summary>
internal static class MSBuildCondition
{
    /// <param name="condition">The raw <c>Condition</c> attribute value.</param>
    /// <param name="expand">Expands property references in a value, or returns <see langword="null"/> when it can't.</param>
    /// <param name="exists">Tests an expanded path for <c>Exists()</c>, or returns <see langword="null"/> when it can't.</param>
    public static bool? Evaluate(string condition, Func<string, string?> expand, Func<string, bool?> exists)
    {
        if (string.IsNullOrWhiteSpace(condition))
        {
            return true;
        }

        var tokens = Tokenize(condition);
        if (tokens == null)
        {
            return null;
        }

        var parser = new Parser(tokens, expand, exists);
        var result = parser.ParseOr();
        return parser.AtEnd && !parser.Failed ? result : null;
    }

    private enum TokenKind { Quoted, Word, Open, Close, Not, Equal, NotEqual, Comma }

    private readonly record struct Token(TokenKind Kind, string Text);

    private static List<Token>? Tokenize(string text)
    {
        var tokens = new List<Token>();
        var i = 0;
        while (i < text.Length)
        {
            var c = text[i];
            if (char.IsWhiteSpace(c))
            {
                i++;
            }
            else if (c == '\'')
            {
                var end = text.IndexOf('\'', i + 1);
                if (end < 0)
                {
                    return null;
                }

                tokens.Add(new Token(TokenKind.Quoted, text[(i + 1)..end]));
                i = end + 1;
            }
            else if (c == '(')
            {
                tokens.Add(new Token(TokenKind.Open, "("));
                i++;
            }
            else if (c == ')')
            {
                tokens.Add(new Token(TokenKind.Close, ")"));
                i++;
            }
            else if (c == ',')
            {
                tokens.Add(new Token(TokenKind.Comma, ","));
                i++;
            }
            else if (c == '=' && i + 1 < text.Length && text[i + 1] == '=')
            {
                tokens.Add(new Token(TokenKind.Equal, "=="));
                i += 2;
            }
            else if (c == '!' && i + 1 < text.Length && text[i + 1] == '=')
            {
                tokens.Add(new Token(TokenKind.NotEqual, "!="));
                i += 2;
            }
            else if (c == '!')
            {
                tokens.Add(new Token(TokenKind.Not, "!"));
                i++;
            }
            else if (c is '<' or '>' or '=')
            {
                // Numeric comparisons are not supported.
                return null;
            }
            else
            {
                var word = new StringBuilder();
                while (i < text.Length && !char.IsWhiteSpace(text[i]) && text[i] is not ('\'' or '(' or ')' or '!' or '=' or '<' or '>' or ','))
                {
                    if (text[i] is '$' or '@' or '%' && i + 1 < text.Length && text[i + 1] == '(')
                    {
                        var close = text.IndexOf(')', i);
                        if (close < 0)
                        {
                            return null;
                        }

                        word.Append(text, i, close - i + 1);
                        i = close + 1;
                    }
                    else
                    {
                        word.Append(text[i++]);
                    }
                }

                tokens.Add(new Token(TokenKind.Word, word.ToString()));
            }
        }

        return tokens;
    }

    private sealed class Parser(List<Token> tokens, Func<string, string?> expand, Func<string, bool?> exists)
    {
        private int _position;

        public bool Failed { get; private set; }

        public bool AtEnd => _position >= tokens.Count;

        private Token? Peek => _position < tokens.Count ? tokens[_position] : null;

        public bool? ParseOr()
        {
            var left = ParseAnd();
            while (IsKeyword("or"))
            {
                _position++;
                var right = ParseAnd();
                left = left == true || right == true ? true : left == null || right == null ? null : false;
            }

            return left;
        }

        private bool? ParseAnd()
        {
            var left = ParseUnary();
            while (IsKeyword("and"))
            {
                _position++;
                var right = ParseUnary();
                left = left == false || right == false ? false : left == null || right == null ? null : true;
            }

            return left;
        }

        private bool? ParseUnary()
        {
            if (Peek?.Kind == TokenKind.Not)
            {
                _position++;
                var operand = ParseUnary();
                return operand == null ? null : !operand;
            }

            return ParsePrimary();
        }

        private bool? ParsePrimary()
        {
            var token = Peek;
            if (token == null)
            {
                Failed = true;
                return null;
            }

            if (token.Value.Kind == TokenKind.Open)
            {
                _position++;
                var inner = ParseOr();
                Expect(TokenKind.Close);
                return inner;
            }

            if (token.Value.Kind == TokenKind.Word &&
                _position + 1 < tokens.Count &&
                tokens[_position + 1].Kind == TokenKind.Open)
            {
                return ParseFunction(token.Value.Text);
            }

            var left = ParseOperand();
            var op = Peek;
            if (op?.Kind is TokenKind.Equal or TokenKind.NotEqual)
            {
                _position++;
                var right = ParseOperand();
                if (left == null || right == null)
                {
                    return null;
                }

                var equal = string.Equals(left, right, StringComparison.OrdinalIgnoreCase);
                return op.Value.Kind == TokenKind.Equal ? equal : !equal;
            }

            if (left == null)
            {
                return null;
            }

            return left.ToUpperInvariant() switch
            {
                "TRUE" or "ON" or "YES" => true,
                "FALSE" or "OFF" or "NO" => false,
                _ => null,
            };
        }

        private bool? ParseFunction(string name)
        {
            _position += 2; // name and '('
            var argument = ParseOperand();
            Expect(TokenKind.Close);
            if (!name.Equals("Exists", StringComparison.OrdinalIgnoreCase) || argument == null)
            {
                return null;
            }

            return exists(argument);
        }

        private string? ParseOperand()
        {
            var token = Peek;
            if (token?.Kind is not (TokenKind.Quoted or TokenKind.Word))
            {
                Failed = true;
                return null;
            }

            _position++;
            return expand(token.Value.Text);
        }

        private bool IsKeyword(string keyword) =>
            Peek is { Kind: TokenKind.Word } token && token.Text.Equals(keyword, StringComparison.OrdinalIgnoreCase);

        private void Expect(TokenKind kind)
        {
            if (Peek?.Kind == kind)
            {
                _position++;
            }
            else
            {
                Failed = true;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO.Abstractions;
using System.Linq;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services;

// A static approximation of MSBuild evaluation, used to find which property definition a package version
// actually resolves to. Only files MSBuild would import are visited (the nearest Directory.Build.props and
// Directory.Packages.props, the project, the nearest Directory.Build.targets, and their resolvable
// <Import>s, in that order). Properties are assigned in document order with last-assignment-wins semantics;
// items are resolved afterwards against the final property values. Where a condition can't be evaluated
// statically, a property assigned under it is marked ambiguous so callers can refuse to guess.
internal sealed class MSBuildEvaluator(IFileSystem fileSystem)
{
    private readonly IFileSystem _fileSystem = fileSystem;

    internal sealed class PropertyDefinition
    {
        public required string Name { get; init; }

        /// <summary>The trimmed text inside the property element.</summary>
        public required string RawValue { get; init; }

        /// <summary>The value after expanding property references, or <see langword="null"/> when that isn't possible.</summary>
        public string? Value { get; init; }

        public required string FilePath { get; init; }

        /// <summary>Index of this element among same-named properties under any <c>PropertyGroup</c> in <see cref="FilePath"/>.</summary>
        public int ElementIndex { get; init; }

        /// <summary>Assigned under a condition that couldn't be evaluated, or derived from such a property.</summary>
        public bool Ambiguous { get; init; }

        /// <summary>When <see cref="RawValue"/> is exactly <c>$(Other)</c>, the name of that property.</summary>
        public string? LinkName { get; init; }

        /// <summary>The definition of <see cref="LinkName"/> in effect when this property was assigned, if any.</summary>
        public PropertyDefinition? Link { get; init; }
    }

    internal sealed class PackageItem
    {
        public required string PackageName { get; init; }
        public required string ElementType { get; init; }
        public required string FilePath { get; init; }
        public required string VersionExpression { get; init; }
        public bool IsVersionOverride { get; init; }
    }

    internal sealed class EvaluationState(string projectPath, string projectDirectory)
    {
        public string ProjectPath { get; } = projectPath;
        public string ProjectDirectory { get; } = projectDirectory;
        public Dictionary<string, PropertyDefinition> Properties { get; } = new(StringComparer.OrdinalIgnoreCase);
        public HashSet<string> ImportedFiles { get; } = new(StringComparer.OrdinalIgnoreCase);

        // Last version-setting item per package, per item type.
        public Dictionary<string, PackageItem> PackageReferences { get; } = new(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, PackageItem> GlobalPackageReferences { get; } = new(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, PackageItem> PackageVersions { get; } = new(StringComparer.OrdinalIgnoreCase);

        // Items in document order, evaluated once all properties are known (MSBuild's item pass follows its property pass).
        public List<(XElement Item, XElement Group, string FilePath)> PendingItems { get; } = [];
    }

    /// <summary>
    /// The MSBuild version variable behind each package version of the project: its evaluated Directory.*.props,
    /// the project file and Directory.Build.targets. Packages whose version is a literal are left out.
    /// </summary>
    public Dictionary<string, PackageVariableInfo> PackageVariables(string projectFilePath) =>
        _fileSystem.File.Exists(projectFilePath)
            ? BuildPackageVariables(Evaluate(projectFilePath, includeProjectFile: true))
            : new Dictionary<string, PackageVariableInfo>(StringComparer.OrdinalIgnoreCase);

    /// <summary>
    /// Evaluates the files MSBuild would import for <paramref name="projectFilePath"/>. Without
    /// <paramref name="includeProjectFile"/> only the Directory.* files are evaluated, as for a file-based app.
    /// </summary>
    public EvaluationState Evaluate(string projectFilePath, bool includeProjectFile)
    {
        var projectFullPath = _fileSystem.Path.GetFullPath(projectFilePath);
        var projectDirectory = _fileSystem.Path.GetDirectoryName(projectFullPath) ?? string.Empty;
        var state = new EvaluationState(projectFullPath, projectDirectory);

        EvaluateFileIfPresent(FindFileAbove(projectDirectory, "Directory.Build.props"), state);
        EvaluateFileIfPresent(FindFileAbove(projectDirectory, "Directory.Packages.props"), state);
        if (includeProjectFile)
        {
            EvaluateFileIfPresent(projectFullPath, state);
        }

        EvaluateFileIfPresent(FindFileAbove(projectDirectory, "Directory.Build.targets"), state);

        var groupConditions = new Dictionary<XElement, bool?>();
        foreach (var (item, group, filePath) in state.PendingItems)
        {
            if (!groupConditions.TryGetValue(group, out var groupCondition))
            {
                groupCondition = groupConditions[group] = EvaluateCondition(group, filePath, state, null);
            }

            if (groupCondition != false)
            {
                EvaluateItem(item, filePath, state);
            }
        }

        return state;
    }

    private string? FindFileAbove(string startDirectory, string fileName)
    {
        var directory = startDirectory;
        while (!string.IsNullOrEmpty(directory))
        {
            var candidate = _fileSystem.Path.Combine(directory, fileName);
            if (_fileSystem.File.Exists(candidate))
            {
                return _fileSystem.Path.GetFullPath(candidate);
            }

            directory = _fileSystem.Path.GetDirectoryName(directory);
        }

        return null;
    }

    private void EvaluateFileIfPresent(string? filePath, EvaluationState state, bool uncertain = false)
    {
        if (string.IsNullOrEmpty(filePath) || !state.ImportedFiles.Add(filePath))
        {
            return;
        }

        XDocument doc;
        try
        {
            doc = XDocument.Parse(_fileSystem.File.ReadAllText(filePath));
        }
        catch
        {
            // Files that can't be read or parsed are ignored, as before.
            return;
        }

        // Element indexes must count every same-named property under any PropertyGroup (including ones that
        // aren't evaluated, such as those inside targets), because that is how the file is later edited.
        var elementIndexes = new Dictionary<XElement, int>();
        foreach (var group in doc.Descendants()
                     .Where(IsPropertyElement)
                     .GroupBy(e => e.Name.LocalName, StringComparer.OrdinalIgnoreCase))
        {
            var index = 0;
            foreach (var element in group)
            {
                elementIndexes[element] = index++;
            }
        }

        if (doc.Root != null)
        {
            EvaluateChildren(doc.Root, filePath, state, elementIndexes, uncertain);
        }
    }

    private void EvaluateChildren(
        XElement parent,
        string filePath,
        EvaluationState state,
        Dictionary<XElement, int> elementIndexes,
        bool uncertain)
    {
        foreach (var element in parent.Elements())
        {
            switch (element.Name.LocalName)
            {
                case "PropertyGroup":
                {
                    // Properties assigned in the group count as empty when undefined, so the group-level default
                    // idiom <PropertyGroup Condition="'$(X)' == ''"><X>...</X></PropertyGroup> can be evaluated.
                    var assigned = element.Elements().Select(e => e.Name.LocalName).ToArray();
                    var groupCondition = EvaluateCondition(element, filePath, state, assigned);
                    if (groupCondition == false)
                    {
                        break;
                    }

                    foreach (var property in element.Elements())
                    {
                        EvaluateProperty(property, filePath, state, elementIndexes, uncertain || groupCondition == null);
                    }

                    break;
                }

                case "ItemGroup":
                {
                    foreach (var item in element.Elements())
                    {
                        state.PendingItems.Add((item, element, filePath));
                    }

                    break;
                }

                case "ImportGroup":
                {
                    var groupCondition = EvaluateCondition(element, filePath, state, null);
                    if (groupCondition != false)
                    {
                        EvaluateChildren(element, filePath, state, elementIndexes, uncertain || groupCondition == null);
                    }

                    break;
                }

                case "Import":
                    EvaluateImport(element, filePath, state, uncertain);
                    break;

                case "Choose":
                    EvaluateChoose(element, filePath, state, elementIndexes, uncertain);
                    break;

                // Targets, UsingTask, ProjectExtensions etc. don't contribute to evaluation.
            }
        }
    }

    private void EvaluateChoose(
        XElement choose,
        string filePath,
        EvaluationState state,
        Dictionary<XElement, int> elementIndexes,
        bool uncertain)
    {
        var anyUnknown = false;
        foreach (var branch in choose.Elements())
        {
            if (branch.Name.LocalName == "When")
            {
                var condition = EvaluateCondition(branch, filePath, state, null);
                if (condition == false)
                {
                    continue;
                }

                anyUnknown |= condition == null;
                EvaluateChildren(branch, filePath, state, elementIndexes, uncertain || anyUnknown);
                if (condition == true)
                {
                    return;
                }
            }
            else if (branch.Name.LocalName == "Otherwise")
            {
                EvaluateChildren(branch, filePath, state, elementIndexes, uncertain || anyUnknown);
                return;
            }
        }
    }

    private void EvaluateProperty(
        XElement property,
        string filePath,
        EvaluationState state,
        Dictionary<XElement, int> elementIndexes,
        bool uncertain)
    {
        var name = property.Name.LocalName;
        var condition = EvaluateCondition(property, filePath, state, [name]);
        if (condition == false)
        {
            return;
        }

        var rawValue = property.Value.Trim();
        var ambiguous = uncertain || condition == null;
        string? linkName = null;
        PropertyDefinition? link = null;
        string? value;

        if (VersionExpression.TryGetSinglePropertyReference(rawValue, out var referenced) && !IsWellKnownProperty(referenced))
        {
            linkName = referenced;
            state.Properties.TryGetValue(referenced, out link);
            ambiguous |= link?.Ambiguous == true;
            value = link?.Value;
        }
        else
        {
            value = Expand(rawValue, filePath, state, null);
        }

        state.Properties[name] = new PropertyDefinition
        {
            Name = name,
            RawValue = rawValue,
            Value = value,
            FilePath = filePath,
            ElementIndex = elementIndexes.TryGetValue(property, out var index) ? index : -1,
            Ambiguous = ambiguous,
            LinkName = linkName,
            Link = link,
        };
    }

    private void EvaluateItem(XElement item, string filePath, EvaluationState state)
    {
        var slot = item.Name.LocalName switch
        {
            "PackageReference" => state.PackageReferences,
            "GlobalPackageReference" => state.GlobalPackageReferences,
            "PackageVersion" => state.PackageVersions,
            _ => null,
        };

        if (slot == null)
        {
            return;
        }

        var remove = GetAttributeValue(item, "Remove");
        if (remove != null)
        {
            // A removal whose condition can't be evaluated is ignored rather than guessed.
            if (EvaluateCondition(item, filePath, state, null) == true)
            {
                foreach (var name in remove.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
                {
                    slot.Remove(name);
                }
            }

            return;
        }

        var packageName = (GetAttributeValue(item, "Include") ?? GetAttributeValue(item, "Update"))?.Trim();
        if (string.IsNullOrEmpty(packageName) ||
            !TryGetPackageVersionExpression(item, out var versionExpression, out var isVersionOverride))
        {
            return;
        }

        // Items whose condition can't be evaluated are treated as applying (the previous behaviour).
        if (EvaluateCondition(item, filePath, state, null) == false)
        {
            return;
        }

        // A later Include or Update that sets a version (literal or not) supersedes earlier ones.
        slot[packageName] = new PackageItem
        {
            PackageName = packageName,
            ElementType = item.Name.LocalName,
            FilePath = filePath,
            VersionExpression = versionExpression.Trim(),
            IsVersionOverride = isVersionOverride,
        };
    }

    private void EvaluateImport(XElement import, string filePath, EvaluationState state, bool uncertain)
    {
        if (GetAttributeValue(import, "Sdk") != null)
        {
            return;
        }

        var condition = EvaluateCondition(import, filePath, state, null);
        if (condition == false)
        {
            return;
        }

        var rawPath = GetAttributeValue(import, "Project");
        if (string.IsNullOrWhiteSpace(rawPath))
        {
            return;
        }

        var expanded = Expand(rawPath.Trim(), filePath, state, null);
        if (string.IsNullOrEmpty(expanded) || expanded.IndexOfAny(['*', '?', ';']) >= 0)
        {
            return;
        }

        var separator = _fileSystem.Path.DirectorySeparatorChar;
        var normalized = expanded.Replace('\\', separator).Replace('/', separator);
        var currentDirectory = _fileSystem.Path.GetDirectoryName(filePath) ?? string.Empty;
        var combined = _fileSystem.Path.IsPathRooted(normalized) ? normalized : _fileSystem.Path.Combine(currentDirectory, normalized);
        var resolved = _fileSystem.Path.GetFullPath(combined);
        if (!_fileSystem.File.Exists(resolved))
        {
            return;
        }

        // An import under an unknown condition is still followed, but what it assigns is ambiguous.
        EvaluateFileIfPresent(resolved, state, uncertain || condition == null);
    }

    private bool? EvaluateCondition(XElement element, string filePath, EvaluationState state, IReadOnlyCollection<string>? assignedProperties)
    {
        var condition = GetAttributeValue(element, "Condition");
        return condition == null
            ? true
            : MSBuildCondition.Evaluate(
                condition,
                text => Expand(text, filePath, state, assignedProperties),
                path => Exists(path, state));
    }

    private bool? Exists(string path, EvaluationState state)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            return false;
        }

        var separator = _fileSystem.Path.DirectorySeparatorChar;
        var normalized = path.Trim().Replace('\\', separator).Replace('/', separator);
        var combined = _fileSystem.Path.IsPathRooted(normalized)
            ? normalized
            : _fileSystem.Path.Combine(state.ProjectDirectory, normalized);
        var fullPath = _fileSystem.Path.GetFullPath(combined);
        return _fileSystem.File.Exists(fullPath) || _fileSystem.Directory.Exists(fullPath);
    }

    private static readonly string[] WellKnownProperties =
    [
        "MSBuildThisFileDirectory", "MSBuildThisFile", "MSBuildThisFileName", "MSBuildThisFileFullPath",
        "MSBuildProjectDirectory", "MSBuildProjectFullPath", "MSBuildProjectFile", "MSBuildProjectName",
    ];

    private static bool IsWellKnownProperty(string name) =>
        WellKnownProperties.Contains(name, StringComparer.OrdinalIgnoreCase);

    // $([MSBuild]::GetPathOfFileAbove('file', 'startDir')) is the usual way a Directory.Build.props imports its parent.
    private static readonly Regex GetPathOfFileAboveRegex = new(
        @"\$\(\[MSBuild\]::GetPathOfFileAbove\(\s*'(?<file>[^'$()]+)'\s*(?:,\s*'(?<dir>[^']*)'\s*)?\)\)",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

    /// <summary>
    /// Expands <c>$(Name)</c> references. Returns <see langword="null"/> when any reference is unknown, ambiguous,
    /// a property function (other than <c>GetPathOfFileAbove</c>), or an item/metadata reference.
    /// An undefined property in <paramref name="assignedProperties"/> (those the condition's element assigns)
    /// expands to empty, so the common <c>Condition="'$(X)' == ''"</c> default pattern can be evaluated.
    /// </summary>
    private string? Expand(string text, string filePath, EvaluationState state, IReadOnlyCollection<string>? assignedProperties)
    {
        if (string.IsNullOrEmpty(text))
        {
            return text ?? string.Empty;
        }

        var failed = false;
        var currentDirectory = _fileSystem.Path.GetDirectoryName(filePath) ?? string.Empty;
        string WithTrailingSlash(string dir) =>
            string.IsNullOrEmpty(dir) ? string.Empty : dir.TrimEnd('\\', '/') + _fileSystem.Path.DirectorySeparatorChar;

        string ExpandSimple(string input) => VersionExpression.PropertyReferenceRegex().Replace(input, match =>
        {
            var name = match.Groups[1].Value;
            switch (name.ToUpperInvariant())
            {
                case "MSBUILDTHISFILEDIRECTORY": return WithTrailingSlash(currentDirectory);
                case "MSBUILDTHISFILE": return _fileSystem.Path.GetFileName(filePath);
                case "MSBUILDTHISFILENAME": return _fileSystem.Path.GetFileNameWithoutExtension(filePath);
                case "MSBUILDTHISFILEFULLPATH": return filePath;
                case "MSBUILDPROJECTDIRECTORY": return state.ProjectDirectory;
                case "MSBUILDPROJECTFULLPATH": return state.ProjectPath;
                case "MSBUILDPROJECTFILE": return _fileSystem.Path.GetFileName(state.ProjectPath);
                case "MSBUILDPROJECTNAME": return _fileSystem.Path.GetFileNameWithoutExtension(state.ProjectPath);
            }

            if (state.Properties.TryGetValue(name, out var definition))
            {
                if (definition.Ambiguous || definition.Value == null)
                {
                    failed = true;
                    return match.Value;
                }

                return definition.Value;
            }

            if (assignedProperties != null && assignedProperties.Contains(name, StringComparer.OrdinalIgnoreCase))
            {
                return string.Empty;
            }

            failed = true;
            return match.Value;
        });

        var expanded = GetPathOfFileAboveRegex.Replace(text, match =>
        {
            var start = match.Groups["dir"].Success ? ExpandSimple(match.Groups["dir"].Value) : currentDirectory;
            if (failed)
            {
                return match.Value;
            }

            start = _fileSystem.Path.IsPathRooted(start) ? start : _fileSystem.Path.Combine(currentDirectory, start);
            return FindFileAbove(_fileSystem.Path.GetFullPath(start), match.Groups["file"].Value) ?? string.Empty;
        });

        expanded = ExpandSimple(expanded);
        if (failed ||
            expanded.Contains("$(", StringComparison.Ordinal) ||
            expanded.Contains("@(", StringComparison.Ordinal) ||
            expanded.Contains("%(", StringComparison.Ordinal))
        {
            return null;
        }

        return expanded;
    }

    internal static bool IsPropertyElement(XElement element) =>
        element.Parent != null &&
        element.Parent.Name.LocalName.Equals("PropertyGroup", StringComparison.OrdinalIgnoreCase);

    private Dictionary<string, PackageVariableInfo> BuildPackageVariables(EvaluationState state)
    {
        var result = new Dictionary<string, PackageVariableInfo>(StringComparer.OrdinalIgnoreCase);
        var packageNames = state.PackageReferences.Keys
            .Concat(state.GlobalPackageReferences.Keys)
            .Concat(state.PackageVersions.Keys)
            .Distinct(StringComparer.OrdinalIgnoreCase);

        foreach (var packageName in packageNames)
        {
            // A version on the PackageReference (Version or VersionOverride) takes precedence over central versions.
            var item = state.PackageReferences.GetValueOrDefault(packageName) ??
                       state.GlobalPackageReferences.GetValueOrDefault(packageName) ??
                       state.PackageVersions[packageName];

            var info = CreatePackageVariableInfo(item, state);
            if (info != null)
            {
                result[packageName] = info;
            }
        }

        return result;
    }

    private static PackageVariableInfo? CreatePackageVariableInfo(PackageItem item, EvaluationState state)
    {
        if (!item.VersionExpression.Contains("$(", StringComparison.Ordinal))
        {
            return null; // Literal version: nothing to preserve.
        }

        var info = new PackageVariableInfo
        {
            PackageName = item.PackageName,
            PackageReferenceFilePath = item.FilePath,
            ElementType = item.ElementType,
            PackageReferenceVersion = item.VersionExpression,
            IsVersionOverride = item.IsVersionOverride,
            VariableValue = string.Empty,
        };

        if (!VersionExpression.TryParse(item.VersionExpression, out var variableName, out _))
        {
            info.VariableName = VersionExpression.PropertyReferenceRegex().Match(item.VersionExpression) is { Success: true } m ? m.Groups[1].Value : string.Empty;
            info.FilePath = item.FilePath;
            info.UnsupportedReason =
                $"its version '{item.VersionExpression}' is neither a single property reference nor a range whose lower bound is a property reference";
            return info;
        }

        // Follow $(A) -> <A>$(B)</A> -> <B>1.0.0</B> to the property that holds the literal version.
        state.Properties.TryGetValue(variableName, out var definition);
        PropertyDefinition? anchor = null;
        string rootName = variableName;
        var ambiguous = false;
        while (definition != null)
        {
            ambiguous |= definition.Ambiguous;
            rootName = definition.Name;
            if (definition.LinkName == null)
            {
                break;
            }

            if (definition.Link == null)
            {
                // The chain ends at a property defined outside the evaluated files (e.g. by an SDK):
                // override it just before the alias that reads it.
                anchor = definition;
                rootName = definition.LinkName;
            }

            definition = definition.Link;
        }

        info.VariableName = rootName;

        if (ambiguous)
        {
            info.FilePath = (definition ?? anchor)?.FilePath ?? item.FilePath;
            info.UnsupportedReason =
                $"the value of $({rootName}) depends on a condition that can't be evaluated statically";
            return info;
        }

        if (definition != null)
        {
            info.FilePath = definition.FilePath;
            info.VariableValue = definition.Value ?? definition.RawValue;
            info.PropertyElementIndex = definition.ElementIndex;
            if (definition.RawValue.Contains("$(", StringComparison.Ordinal) ||
                definition.RawValue.Contains("@(", StringComparison.Ordinal) ||
                definition.RawValue.Contains("%(", StringComparison.Ordinal))
            {
                info.UnsupportedReason = $"$({rootName}) is defined by the expression '{definition.RawValue}' rather than a version";
            }
        }
        else if (anchor != null)
        {
            info.FilePath = anchor.FilePath;
            info.InsertBeforeProperty = (anchor.Name, anchor.ElementIndex);
        }
        else
        {
            // Not defined in any evaluated file (e.g. $(MauiVersion) from a workload): define it next to the reference.
            info.FilePath = item.FilePath;
            info.InsertProperty = true;
        }

        return info;
    }

    private static bool TryGetPackageVersionExpression(XElement element, out string versionValue, out bool isVersionOverride)
    {
        var overrideValue = GetAttributeOrElementValue(element, "VersionOverride");
        if (!string.IsNullOrEmpty(overrideValue))
        {
            versionValue = overrideValue;
            isVersionOverride = true;
            return true;
        }

        versionValue = GetAttributeOrElementValue(element, "Version") ?? string.Empty;
        isVersionOverride = false;
        return !string.IsNullOrEmpty(versionValue);
    }

    private static string? GetAttributeOrElementValue(XElement element, string name) =>
        GetAttributeValue(element, name) ??
        element.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(name, StringComparison.OrdinalIgnoreCase))?.Value.Trim();

    private static string? GetAttributeValue(XElement element, string name) =>
        element.Attributes().FirstOrDefault(a => a.Name.LocalName.Equals(name, StringComparison.OrdinalIgnoreCase))?.Value;
}

using System;
using System.Collections.Generic;
using System.IO.Abstractions;
using System.Linq;
using System.Xml.Linq;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services;

/// <summary>
/// Writes a new version to the MSBuild property behind a package version (<c>Version="$(V)"</c> or
/// <c>Version="[$(V), 2.0.0)"</c>) and makes the reference read that property again, in case <c>dotnet add package</c>
/// replaced it with a literal. Edits are made to the text so the rest of each file keeps its formatting, encoding
/// and byte order mark.
/// </summary>
internal sealed class MSBuildVariableWriter(IFileSystem fileSystem, Action<string>? onWarning = null)
{
    private readonly IFileSystem _fileSystem = fileSystem;
    private readonly Action<string>? _onWarning = onWarning;

    /// <returns><see langword="true"/> when any file was changed.</returns>
    public bool TryUpdate(PackageVariableInfo variableInfo, VersionRange newRange)
    {
        ArgumentNullException.ThrowIfNull(newRange);
        if (!newRange.HasLowerBound)
        {
            throw new ArgumentException($"Version range '{newRange}' must have a lower bound.", nameof(newRange));
        }

        try
        {
            return Update(variableInfo, newRange);
        }
        catch (Exception ex)
        {
            _onWarning?.Invoke(
                $"Failed to update package reference '{variableInfo.PackageName}' ({variableInfo.ElementType}): {ex.Message}");
            return false;
        }
    }

    /// <summary>Whether the variable already holds a value that makes the reference evaluate to <paramref name="versionRange"/>.</summary>
    public static bool IsAtVersionRange(PackageVariableInfo variableInfo, VersionRange versionRange)
    {
        var expression = string.IsNullOrWhiteSpace(variableInfo.PackageReferenceVersion)
            ? $"$({variableInfo.VariableName})"
            : variableInfo.PackageReferenceVersion;

        return VersionExpression.TryEvaluate(expression, variableInfo.VariableValue, out var current) &&
               current.Equals(versionRange);
    }

    private bool Update(PackageVariableInfo variableInfo, VersionRange newRange)
    {
        if (variableInfo.UnsupportedReason != null)
        {
            _onWarning?.Invoke(
                $"Not preserving the version variable of '{variableInfo.PackageName}': {variableInfo.UnsupportedReason}.");
            return false;
        }

        // $(V) holds the whole requested range; in [$(V), upper) it holds only the lower bound.
        var isRangeExpression = !string.IsNullOrWhiteSpace(variableInfo.PackageReferenceVersion) &&
                                VersionExpression.TryParse(variableInfo.PackageReferenceVersion, out _, out var isRange) &&
                                isRange;
        var propertyValueToWrite = isRangeExpression ? newRange.MinVersion!.ToString() : newRange.ToVersionString();

        // Step 1: Update the property value in the file where it's defined (or insert it if implicit/SDK-defined)
        var propertyWrite = TryWriteProperty(variableInfo, propertyValueToWrite);
        if (propertyWrite == PropertyWrite.Failed)
        {
            // Restoring the reference now would make the package resolve to the property's old value.
            return false;
        }

        var updated = propertyWrite == PropertyWrite.Written;

        // Step 2: Restore the variable reference in the PackageReference file (might be different from property file)
        string packageRefFilePath = variableInfo.PackageReferenceFilePath;
        if (_fileSystem.File.Exists(packageRefFilePath))
        {
            var packageRefFile = EncodedText.Read(_fileSystem, packageRefFilePath);
            string packageRefContent = packageRefFile.Content;
            _ = XDocument.Parse(packageRefContent);

            var versionExpression = string.IsNullOrEmpty(variableInfo.PackageReferenceVersion)
                ? $"$({variableInfo.VariableName})"
                : isRangeExpression
                    ? VersionExpression.Compute(variableInfo.PackageReferenceVersion, ReferencedVariableName(variableInfo), newRange)
                    : variableInfo.PackageReferenceVersion;

            var newPackageRefContent = PackageVersionMarkup.ReplacePackageVersion(
                packageRefContent,
                [variableInfo.ElementType],
                variableInfo.PackageName,
                versionExpression,
                variableInfo.PackageReferenceVersion,
                newRange);

            if (!string.Equals(packageRefContent, newPackageRefContent, StringComparison.Ordinal))
            {
                packageRefFile.Write(_fileSystem, packageRefFilePath, newPackageRefContent);
                updated = true;
            }
        }

        return updated;
    }

    private static string ReferencedVariableName(PackageVariableInfo variableInfo) =>
        VersionExpression.TryParse(variableInfo.PackageReferenceVersion, out var name, out _) ? name : variableInfo.VariableName;

    private enum PropertyWrite { Written, AlreadyCurrent, Failed }

    private PropertyWrite TryWriteProperty(PackageVariableInfo variableInfo, string newValue)
    {
        if (string.IsNullOrEmpty(variableInfo.FilePath) ||
            string.IsNullOrEmpty(variableInfo.VariableName) ||
            !_fileSystem.File.Exists(variableInfo.FilePath))
        {
            return PropertyWrite.Failed;
        }

        var propertyFile = EncodedText.Read(_fileSystem, variableInfo.FilePath);
        var content = propertyFile.Content;
        var doc = XDocument.Parse(content);
        string newContent;

        if (variableInfo.InsertBeforeProperty is { } anchor)
        {
            newContent = PackageVersionMarkup.InsertPropertyBefore(content, anchor.Name, anchor.Index, variableInfo.VariableName, newValue);
        }
        else if (variableInfo.InsertProperty || variableInfo.PropertyElementIndex < 0)
        {
            var elements = PropertyElements(doc, variableInfo.VariableName);
            var topLevel = elements.FindLastIndex(e => e.Parent != null && IsUnconditionalTopLevel(e.Parent) && e.Attribute("Condition") == null);
            newContent = topLevel >= 0
                // Already defined (for example by an earlier upgrade that inserted it): update that definition.
                ? PackageVersionMarkup.ReplacePropertyValueAt(content, variableInfo.VariableName, topLevel, newValue)
                : !variableInfo.InsertProperty && elements.Count > 0
                    // Callers that don't say which definition: the last one.
                    ? PackageVersionMarkup.ReplacePropertyValueAt(content, variableInfo.VariableName, elements.Count - 1, newValue)
                    : PackageVersionMarkup.InsertProperty(content, InsertionGroupIndex(doc), variableInfo.VariableName, newValue);
        }
        else
        {
            var elements = PropertyElements(doc, variableInfo.VariableName);
            var index = variableInfo.PropertyElementIndex;
            if (index < elements.Count && string.Equals(elements[index].Value.Trim(), newValue, StringComparison.Ordinal))
            {
                return PropertyWrite.AlreadyCurrent;
            }

            if (index >= elements.Count ||
                (!string.IsNullOrEmpty(variableInfo.VariableValue) &&
                 !string.Equals(elements[index].Value.Trim(), variableInfo.VariableValue, StringComparison.Ordinal)))
            {
                _onWarning?.Invoke(
                    $"Not updating $({variableInfo.VariableName}) in '{variableInfo.FilePath}': the file changed since it was scanned.");
                return PropertyWrite.Failed;
            }

            newContent = PackageVersionMarkup.ReplacePropertyValueAt(content, variableInfo.VariableName, index, newValue);
        }

        if (string.Equals(content, newContent, StringComparison.Ordinal))
        {
            return PropertyWrite.AlreadyCurrent;
        }

        if (!IsExpectedPropertyEdit(doc, newContent, variableInfo.VariableName, newValue))
        {
            _onWarning?.Invoke(
                $"Not updating $({variableInfo.VariableName}) in '{variableInfo.FilePath}': the edit did not change exactly one definition as expected.");
            return PropertyWrite.Failed;
        }

        propertyFile.Write(_fileSystem, variableInfo.FilePath, newContent);
        return PropertyWrite.Written;
    }

    // Guards the text-level edit against regex/XML disagreements: the edited document must still parse, and
    // exactly one definition of the property must differ (holding newValue) or have been added; nothing else
    // about the property's definitions may change.
    private static bool IsExpectedPropertyEdit(XDocument before, string newContent, string propertyName, string newValue)
    {
        XDocument after;
        try
        {
            after = XDocument.Parse(newContent);
        }
        catch (System.Xml.XmlException)
        {
            return false;
        }

        var oldValues = PropertyElements(before, propertyName).Select(e => e.Value.Trim()).ToList();
        var newValues = PropertyElements(after, propertyName).Select(e => e.Value.Trim()).ToList();

        if (newValues.Count == oldValues.Count)
        {
            var changed = Enumerable.Range(0, oldValues.Count).Where(i => oldValues[i] != newValues[i]).ToList();
            return changed.Count == 1 && newValues[changed[0]] == newValue;
        }

        if (newValues.Count != oldValues.Count + 1)
        {
            return false;
        }

        // Inserted: removing one occurrence of newValue must give back the original sequence.
        for (var i = 0; i < newValues.Count; i++)
        {
            if (newValues[i] == newValue && newValues.Where((_, j) => j != i).SequenceEqual(oldValues))
            {
                return true;
            }
        }

        return false;
    }

    private static List<XElement> PropertyElements(XDocument doc, string propertyName) =>
        doc.Descendants()
            .Where(e => MSBuildEvaluator.IsPropertyElement(e) && e.Name.LocalName.Equals(propertyName, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private static bool IsUnconditionalTopLevel(XElement propertyGroup) =>
        propertyGroup.Parent != null &&
        propertyGroup.Parent == propertyGroup.Document?.Root &&
        propertyGroup.Attribute("Condition") == null;

    // The first unconditional PropertyGroup directly under <Project> (not in a target, Choose or conditional
    // group), as an index among the non-empty PropertyGroups that PackageVersionMarkup counts; -1 for a new group.
    private static int InsertionGroupIndex(XDocument doc) =>
        doc.Descendants()
            .Where(e => e.Name.LocalName.Equals("PropertyGroup", StringComparison.OrdinalIgnoreCase) && !e.IsEmpty)
            .ToList()
            .FindIndex(IsUnconditionalTopLevel);
}

using NuGet.Common;
using NuGet.Configuration;
using NuGet.Frameworks;
using NuGet.Protocol;
using NuGet.Protocol.Core.Types;
using NuGet.Versioning;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace DotNetOutdated.Core.Services
{
    using System.Collections.Concurrent;

    internal sealed class NuGetPackageInfoService : INuGetPackageInfoService, IDisposable
    {
        // The enabled sources and the package source mapping come from the same settings and are published together,
        // so a concurrent first call never sees sources without their mapping (which would query unmapped sources).
        private SourceSettings? _sourceSettings;

        private readonly SourceCacheContext _context;

        private readonly ConcurrentDictionary<string, Task<PackageMetadataResource?>> _metadataResourceRequests = [];

        public NuGetPackageInfoService()
        {
            _context = new SourceCacheContext()
            {
                NoCache = true
            };
        }

        private sealed record SourceSettings(IEnumerable<PackageSource> EnabledSources, PackageSourceMapping PackageSourceMapping);

        private SourceSettings GetSourceSettings(string? root)
        {
            if (_sourceSettings == null)
            {
                var settings = Settings.LoadDefaultSettings(root);
                _sourceSettings = new SourceSettings(
                    SettingsUtility.GetEnabledSources(settings),
                    PackageSourceMapping.GetPackageSourceMapping(settings));
            }

            return _sourceSettings;
        }

        [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1031:Do not catch general exception types", Justification = "This method is supposed to fail silently")]
        private async Task<PackageMetadataResource?> FindMetadataResourceForSource(Uri source, string? projectFilePath, string packageId, CancellationToken cancellationToken)
        {
            try
            {
                string resourceUrl = source.AbsoluteUri;

                // We try and create the source repository from the enable sources we loaded from config.
                // This allows us to inherit the username/password for the source from the config and thus
                // enables secure feeds to work properly
                var sourceSettings = GetSourceSettings(projectFilePath);
                var enabledSource = sourceSettings.EnabledSources.FirstOrDefault(s => s.SourceUri == source);


                if (enabledSource != null && sourceSettings.PackageSourceMapping.IsEnabled)
                {
                    var mappedSources = sourceSettings.PackageSourceMapping.GetConfiguredPackageSources(packageId);
                    if (mappedSources != null && !mappedSources.Any(s => string.Equals(s, enabledSource.Name, StringComparison.OrdinalIgnoreCase)))
                    {
                        // Skip package sources that are not mapped to the package
                        return null;
                    }
                }

                var sourceRepository = enabledSource != null
                                           ? new SourceRepository(enabledSource, Repository.Provider.GetCoreV3())
                                           : Repository.Factory.GetCoreV3(resourceUrl);

                // The discovery request is cached per source and shared, so it doesn't take this caller's token; the caller
                // only stops waiting for it.
                var metadataResourceRequest = _metadataResourceRequests.GetOrAdd(resourceUrl, _ => sourceRepository.GetResourceAsync<PackageMetadataResource>());

                return await metadataResourceRequest.WaitAsync(cancellationToken).ConfigureAwait(false);
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                throw;
            }
            catch (Exception)
            {
                return null;
            }
        }

        public async Task<IReadOnlyList<NuGetVersion>> GetAllVersionsAsync(PackageVersionsQuery query, CancellationToken cancellationToken = default)
        {
            ArgumentNullException.ThrowIfNull(query);
            var package = query.PackageId;
            var sources = query.Sources;
            var includePrerelease = query.IncludePrerelease;
            var targetFramework = query.TargetFramework;
            var projectFilePath = query.ProjectFilePath;
            var isDevelopmentDependency = query.IsDevelopmentDependency;
            var olderThanDays = query.OlderThanDays;
            var ignoreFailedSources = query.IgnoreFailedSources;

            var allVersions = new List<NuGetVersion>();
            foreach (var source in sources)
            {
                try
                {
                    var metadata = await FindMetadataResourceForSource(source, projectFilePath, package, cancellationToken).ConfigureAwait(false);
                    if (metadata != null)
                    {
                        var compatibleMetadataList = await metadata.GetMetadataAsync(package, includePrerelease, false, _context, NullLogger.Instance, cancellationToken).ConfigureAwait(false);

                        if (olderThanDays > 0)
                        {
                            compatibleMetadataList = compatibleMetadataList.Where(c => !c.Published.HasValue ||
                                                                                       c.Published <= DateTimeOffset.UtcNow.AddDays(-olderThanDays));
                        }

                        // We need to ensure that we only get package versions which are compatible with the requested target framework.
                        // For development dependencies, we do not perform this check
                        if (!isDevelopmentDependency)
                        {
                            var reducer = new FrameworkReducer();

                            compatibleMetadataList = compatibleMetadataList
                                .Where(meta => meta.DependencySets?.Any() != true ||
                                               reducer.GetNearest(targetFramework, meta.DependencySets.Select(ds => ds.TargetFramework)) != null);
                        }

                        foreach (var m in compatibleMetadataList)
                        {
                            if (m is PackageSearchMetadata packageSearchMetadata)
                            {
                                allVersions.Add(packageSearchMetadata.Version);
                            }
                            else if (m is PackageSearchMetadataV2Feed packageSearchMetadataV2Feed)
                            {
                                allVersions.Add(packageSearchMetadataV2Feed.Version);
                            }
                            else if (m is LocalPackageSearchMetadata localPackageSearchMetadata)
                            {
                                allVersions.Add(localPackageSearchMetadata.Identity.Version);
                            }
                            else
                            {
                                allVersions.Add(m.Identity.Version);
                            }
                        }
                    }
                }
                catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
                {
                    throw;
                }
                catch (HttpRequestException)
                {
                    // Suppress HTTP errors when connecting to NuGet sources
                }
                catch (Exception ex)
                {
                    if (!ignoreFailedSources)
                    {
                        continue;
                    }
                    // if the inner exception is NOT HttpRequestException, throw it
                    if (ex.InnerException != null && !(ex.InnerException is HttpRequestException)) throw;
                }
            }

            return allVersions;
        }

        public void Dispose()
        {
            _context?.Dispose();
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services
{
    internal class NuGetPackageResolutionService(INuGetPackageInfoService nugetService) : INuGetPackageResolutionService
    {
        private readonly INuGetPackageInfoService _nugetService = nugetService;
        private readonly ConcurrentDictionary<string, Lazy<Task<IReadOnlyList<NuGetVersion>>>> _cache = [];

        public async Task<NuGetVersion> ResolveLatestVersionAsync(LatestVersionQuery query, CancellationToken cancellationToken = default)
        {
            ArgumentNullException.ThrowIfNull(query);
            var packageName = query.PackageId;
            var referencedVersion = query.CurrentVersion;
            var currentVersionRange = query.AllowedRange;
            var versionLock = query.VersionLock;
            var prerelease = query.Prerelease;
            var prereleaseLabel = query.PrereleaseLabel;
            var targetFrameworkName = query.TargetFramework;
            var olderThanDays = query.OlderThanDays;

            ArgumentNullException.ThrowIfNull(referencedVersion);
            ArgumentNullException.ThrowIfNull(currentVersionRange);

            if (currentVersionRange.MinVersion is null)
                throw new ArgumentException($"No minimum version specified for package {packageName}.", nameof(query));

            // Determine whether we are interested in pre-releases
            bool includePrerelease = referencedVersion.IsPrerelease;
            if (prerelease == PrereleaseReporting.Always)
                includePrerelease = true;
            else if (prerelease == PrereleaseReporting.Never)
                includePrerelease = false;

            string cacheKey = (packageName + "-" + includePrerelease + "-" + targetFrameworkName + "-" + olderThanDays).ToUpperInvariant();

            // Get all the available versions
            // The request is shared by every caller with the same key, so it doesn't take one caller's cancellation token.
            var allVersionsRequest = new Lazy<Task<IReadOnlyList<NuGetVersion>>>(() => _nugetService.GetAllVersionsAsync(
                new PackageVersionsQuery
                {
                    PackageId = packageName,
                    Sources = query.Sources,
                    TargetFramework = targetFrameworkName,
                    ProjectFilePath = query.ProjectFilePath,
                    IncludePrerelease = includePrerelease,
                    IsDevelopmentDependency = query.IsDevelopmentDependency,
                    OlderThanDays = olderThanDays,
                    IgnoreFailedSources = query.IgnoreFailedSources,
                },
                CancellationToken.None));
            var allVersions = await _cache.GetOrAdd(cacheKey, allVersionsRequest).Value.WaitAsync(cancellationToken).ConfigureAwait(false);

            // Determine the floating behaviour
            var floatingBehaviour = includePrerelease ? NuGetVersionFloatBehavior.AbsoluteLatest : NuGetVersionFloatBehavior.Major;
            if (versionLock == VersionLock.Major)
                floatingBehaviour = includePrerelease ? NuGetVersionFloatBehavior.PrereleaseMinor : NuGetVersionFloatBehavior.Minor;
            if (versionLock == VersionLock.Minor)
                floatingBehaviour = includePrerelease ? NuGetVersionFloatBehavior.PrereleasePatch : NuGetVersionFloatBehavior.Patch;

            string releasePrefix = string.Empty;
            if (referencedVersion.IsPrerelease)
            {
                if (!string.IsNullOrWhiteSpace(prereleaseLabel))
                {
                    releasePrefix = prereleaseLabel;
                }
                else
                {
                    releasePrefix = referencedVersion.ReleaseLabels.First();
                }
            }

            // Create a new version range for comparison
            var latestVersionRange = new VersionRange(currentVersionRange, new FloatRange(floatingBehaviour, referencedVersion, releasePrefix));

            // Use new version range to determine latest version
            NuGetVersion? latestVersion = latestVersionRange.FindBestMatch(allVersions);

            return latestVersion ?? referencedVersion;
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using DotNetOutdated.Core.Models;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services;

/// <summary>
/// Reports which dependencies of analyzed projects have newer versions, applying the filters and version settings of
/// <see cref="OutdatedOptions"/>. Up to one project per processor is looked up at a time, with the target frameworks and
/// dependencies of each project looked up concurrently.
/// </summary>
internal sealed class OutdatedDependencyService(INuGetPackageResolutionService resolutionService) : IOutdatedDependencyService
{
    private readonly INuGetPackageResolutionService _resolutionService = resolutionService;

    public async Task<IReadOnlyList<OutdatedProject>> FindOutdatedAsync(
        IEnumerable<Project> projects,
        OutdatedOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(projects);
        options ??= OutdatedOptions.Default;
        cancellationToken.ThrowIfCancellationRequested();

        var results = new ConcurrentBag<OutdatedProject>();
        await Parallel.ForEachAsync(projects, cancellationToken, async (project, token) =>
        {
            if (await FindOutdatedAsync(project, options, token).ConfigureAwait(false) is { } outdated)
            {
                results.Add(outdated);
            }
        }).ConfigureAwait(false);

        return results
            .OrderBy(project => project.Name)
            .ThenBy(project => project.FilePath)
            .ToList();
    }

    private async Task<OutdatedProject?> FindOutdatedAsync(Project project, OutdatedOptions options, CancellationToken cancellationToken)
    {
        var frameworks = await Task.WhenAll(project.TargetFrameworks.Select(targetFramework =>
            FindOutdatedAsync(project, targetFramework, options, cancellationToken))).ConfigureAwait(false);

        var outdatedFrameworks = frameworks
            .OfType<OutdatedTargetFramework>()
            .OrderBy(targetFramework => targetFramework.Name.Framework)
            .ToList();

        return outdatedFrameworks.Count == 0
            ? null
            : new OutdatedProject { Name = project.Name, FilePath = project.FilePath, TargetFrameworks = outdatedFrameworks };
    }

    private async Task<OutdatedTargetFramework?> FindOutdatedAsync(
        Project project,
        TargetFramework targetFramework,
        OutdatedOptions options,
        CancellationToken cancellationToken)
    {
        var dependencies = targetFramework.Dependencies
            .Where(dependency => options.IncludeAutoReferences || !dependency.IsAutoReferenced)
            .Where(dependency => options.IncludeFilters.Count == 0 || options.IncludeFilters.Any(filter => NameContains(dependency, filter)))
            .Where(dependency => !options.ExcludeFilters.Any(filter => NameContains(dependency, filter)));

        var results = await Task.WhenAll(dependencies.Select(dependency =>
            FindOutdatedAsync(project, targetFramework, dependency, options, cancellationToken))).ConfigureAwait(false);

        var outdatedDependencies = results
            .OfType<OutdatedDependency>()
            .OrderBy(dependency => dependency.Dependency.Name)
            .ToList();

        return outdatedDependencies.Count == 0
            ? null
            : new OutdatedTargetFramework
            {
                Name = targetFramework.Name,
                TargetAlias = targetFramework.TargetAlias,
                Dependencies = outdatedDependencies,
            };
    }

    private async Task<OutdatedDependency?> FindOutdatedAsync(
        Project project,
        TargetFramework targetFramework,
        Dependency dependency,
        OutdatedOptions options,
        CancellationToken cancellationToken)
    {
        var resolvedVersion = dependency.ResolvedVersion;
        var allowedRange = CapAtMaximumVersion(dependency.VersionRange, options.MaximumVersion);

        // Otherwise the latest version is unknown, and OutdatedDependency.LatestVersionUnknownReason says why.
        LatestVersionQuery? query = OutdatedDependency.CanLookUpLatestVersion(dependency)
            ? new LatestVersionQuery
            {
                PackageId = dependency.Name,
                CurrentVersion = resolvedVersion!,
                AllowedRange = allowedRange,
                Sources = project.Sources.ToList(),
                TargetFramework = targetFramework.Name,
                ProjectFilePath = project.FilePath,
                IsDevelopmentDependency = dependency.IsDevelopmentDependency,
                VersionLock = options.VersionLock,
                Prerelease = options.Prerelease,
                PrereleaseLabel = options.PrereleaseLabel,
                OlderThanDays = options.OlderThanDays,
                IgnoreFailedSources = options.IgnoreFailedSources,
            }
            : null;

        var latestVersion = query == null
            ? null
            : await _resolutionService.ResolveLatestVersionAsync(query, cancellationToken).ConfigureAwait(false);

        // The resolution service returns the resolved version when nothing newer is allowed (including when no newer
        // version is older than OlderThanDays), so an unknown latest version is still reported.
        if (latestVersion != null && latestVersion == resolvedVersion && !options.IncludeUpToDate)
        {
            return null;
        }

        return new OutdatedDependency { Dependency = dependency, LatestVersion = latestVersion };
    }

    // The effective upper bound is whichever of the declared range and the maximum version is lower, so pinned
    // versions ([1.0.0]) and bounded ranges ([1.0.0, 2.0.0)) are never widened.
    private static VersionRange CapAtMaximumVersion(VersionRange range, NuGetVersion? maximumVersion) =>
        maximumVersion is not null && (range.MaxVersion is null || maximumVersion < range.MaxVersion)
            ? new VersionRange(range.MinVersion, range.IsMinInclusive, maximumVersion, includeMaxVersion: true, range.Float, range.OriginalString)
            : range;

    private static bool NameContains(Dependency dependency, string part) =>
        dependency.Name.Contains(part, StringComparison.InvariantCultureIgnoreCase);
}

namespace DotNetOutdated.Core.Services;

/// <summary>
/// A package version written through an MSBuild property (<c>Version="$(V)"</c>, <c>#:package Id@$(V)</c>):
/// where the property is defined and where the reference that reads it is.
/// </summary>
internal sealed class PackageVariableInfo
{
    public const string FileBasedPackageDirectiveElementType = "FileBasedPackageDirective";

    public const string FileBasedSdkDirectiveElementType = "FileBasedSdkDirective";

    public required string PackageName { get; set; }
    public string VariableName { get; set; } = string.Empty;
    public required string VariableValue { get; set; }
    public string FilePath { get; set; } = string.Empty;  // Where the property is DEFINED
    public required string PackageReferenceFilePath { get; set; }  // Where the PackageReference/PackageVersion is USED
    public required string ElementType { get; set; }
    public string? PackageReferenceName { get; set; }
    public string PackageReferenceVersion { get; set; } = string.Empty;
    public bool IsVersionOverride { get; set; }

    /// <summary>
    /// Why the variable can't be updated safely (for example an unsupported version expression, or a property
    /// assigned under a condition that can't be evaluated statically); <see langword="null"/> when it can.
    /// </summary>
    public string? UnsupportedReason { get; set; }

    /// <summary>Which same-named property element in <see cref="FilePath"/> is in effect; -1 when unknown.</summary>
    public int PropertyElementIndex { get; set; } = -1;

    /// <summary>The variable isn't defined in any evaluated file and must be added to <see cref="FilePath"/>.</summary>
    public bool InsertProperty { get; set; }

    /// <summary>The variable is SDK-defined and read by this alias property: add an override just before it.</summary>
    public (string Name, int Index)? InsertBeforeProperty { get; set; }

    public bool IsFileBasedDirective =>
        ElementType is FileBasedPackageDirectiveElementType or FileBasedSdkDirectiveElementType;

    /// <summary>The kind of reference that reads the variable.</summary>
    public ReferenceKind ReferenceKind =>
        ElementType == FileBasedSdkDirectiveElementType ? ReferenceKind.Sdk : ReferenceKind.Package;
}

using System;
using System.Text.RegularExpressions;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services
{
    /// <summary>
    /// Text-level edits to package version attributes and MSBuild properties that keep the rest of the file byte-for-byte.
    /// </summary>
    internal static class PackageVersionMarkup
    {
        internal static readonly string[] CentralPackageElements = ["PackageVersion", "GlobalPackageReference"];

        // One complete attribute: name, '=', and a whole quoted value (which may contain '>' or the other quote).
        private const string AttributePattern = @"[^\s=/>]+\s*=\s*(?:""[^""]*""|'[^']*')";
        private const string InactiveMarkupPattern = @"<!--[\s\S]*?-->|<!\[CDATA\[[\s\S]*?\]\]>|<\?[\s\S]*?\?>";

        private static readonly Regex Attribute = new(
            @"(?<name>[^\s=/>]+)\s*=\s*(?<quote>[""'])(?<value>.*?)\k<quote>",
            RegexOptions.Singleline | RegexOptions.CultureInvariant);

        private static readonly Regex PropertyGroupPattern = new(
            InactiveMarkupPattern + @"|(?<open><PropertyGroup(?:\s+" + AttributePattern + @")*\s*>)(?<body>[\s\S]*?)(?<close></PropertyGroup\s*>)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        private static readonly Regex ProjectOpenTagPattern = new(
            InactiveMarkupPattern + @"|(?<open><Project(?:\s+" + AttributePattern + @")*\s*>)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        /// <summary>
        /// Replaces the <c>Version</c> attribute value of every <paramref name="elementNames"/> element whose
        /// <c>Include</c> or <c>Update</c> is <paramref name="packageName"/> (case-insensitive). Attributes may be
        /// in any order, use either quote style, have spaces around <c>=</c> and span several lines.
        /// Markup inside comments, CDATA sections and processing instructions is left untouched.
        /// </summary>
        public static string ReplaceVersion(string content, string[] elementNames, string packageName, string newValue) =>
            ReplaceVersion(content, elementNames, packageName, newValue, out _);

        /// <inheritdoc cref="ReplaceVersion(string, string[], string, string)"/>
        /// <param name="matched">True when at least one element matched, even if it already had <paramref name="newValue"/>.</param>
        public static string ReplaceVersion(string content, string[] elementNames, string packageName, string newValue, out bool matched) =>
            ReplaceVersionAttributes(content, elementNames, packageName, newValue, allowVersionOverride: false, skipExistingVariables: false, out matched);

        /// <summary>
        /// Restores a variable reference in <c>Version</c> or <c>VersionOverride</c> attributes or child elements
        /// for <paramref name="packageName"/>. Values that contain a property reference are left untouched unless they
        /// equal <paramref name="previousExpression"/> (the expression being rewritten). When
        /// <paramref name="expectedLiteral"/> is given, literal values are only replaced when they equal it (the version
        /// <c>dotnet add package</c> wrote), so other pins of the package, such as one under another condition, are kept.
        /// </summary>
        public static string ReplacePackageVersion(
            string content,
            string[] elementNames,
            string packageName,
            string newValue,
            string? previousExpression = null,
            VersionRange? expectedLiteral = null)
        {
            var result = ReplaceVersionAttributes(
                content, elementNames, packageName, newValue, allowVersionOverride: true, skipExistingVariables: true, out _, previousExpression, expectedLiteral);

            var elements = string.Join("|", Array.ConvertAll(elementNames, Regex.Escape));
            var childElementPattern =
                InactiveMarkupPattern + "|" +
                $@"(?<open><(?<elem>{elements})(?<attributes>(?:\s+{AttributePattern})*)\s*>)(?<body>[\s\S]*?)(?<close></\k<elem>\s*>)";
            var childVersionPattern =
                InactiveMarkupPattern + "|" +
                $@"(?<vopen><(?<vtag>VersionOverride|Version)(?:\s+{AttributePattern})*\s*>)(?<vval>[\s\S]*?)(?<vclose></\k<vtag>\s*>)";

            return Regex.Replace(
                result,
                childElementPattern,
                m =>
                {
                    if (!m.Groups["open"].Success ||
                        !MatchesPackage(m.Groups["attributes"].Value, packageName, allowVersionOverride: true, out var versionAttr) ||
                        versionAttr != null)
                    {
                        return m.Value;
                    }

                    var newBody = Regex.Replace(
                        m.Groups["body"].Value,
                        childVersionPattern,
                        vm => !vm.Groups["vopen"].Success || !IsRestorable(vm.Groups["vval"].Value, previousExpression, expectedLiteral)
                            ? vm.Value
                            : vm.Groups["vopen"].Value + ReplaceTrimmed(vm.Groups["vval"].Value, newValue) + vm.Groups["vclose"].Value,
                        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

                    return m.Groups["open"].Value + newBody + m.Groups["close"].Value;
                },
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static string ReplaceVersionAttributes(
            string content,
            string[] elementNames,
            string packageName,
            string newValue,
            bool allowVersionOverride,
            bool skipExistingVariables,
            out bool matched,
            string? previousExpression = null,
            VersionRange? expectedLiteral = null)
        {
            var elements = string.Join("|", Array.ConvertAll(elementNames, Regex.Escape));
            var pattern =
                InactiveMarkupPattern + "|" +
                $@"<(?:{elements})(?<attributes>(?:\s+{AttributePattern})*)\s*/?>";

            var found = false;
            var result = Regex.Replace(
                content,
                pattern,
                m =>
                {
                    var attributes = m.Groups["attributes"];
                    if (!attributes.Success ||
                        !MatchesPackage(attributes.Value, packageName, allowVersionOverride, out var version) ||
                        version == null ||
                        (skipExistingVariables && !IsRestorable(version.Value, previousExpression, expectedLiteral)))
                    {
                        return m.Value;
                    }

                    found = true;
                    var start = attributes.Index - m.Index + version.Index;
                    return string.Concat(m.Value.AsSpan(0, start), newValue, m.Value.AsSpan(start + version.Length));
                },
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

            matched = found;
            return result;
        }

        private static bool IsRestorable(string value, string? previousExpression, VersionRange? expectedLiteral)
        {
            var trimmed = value.Trim();
            if (previousExpression != null && string.Equals(trimmed, previousExpression.Trim(), StringComparison.Ordinal))
            {
                return true;
            }

            if (trimmed.Contains("$(", StringComparison.Ordinal))
            {
                return false;
            }

            return expectedLiteral == null ||
                   (VersionRange.TryParse(trimmed, out var literal) && literal.Equals(expectedLiteral));
        }

        private static bool MatchesPackage(string attributesText, string packageName, bool allowVersionOverride, out Group? version)
        {
            Group? versionAttr = null;
            Group? overrideAttr = null;
            var isPackage = false;

            foreach (Match attribute in Attribute.Matches(attributesText))
            {
                var name = attribute.Groups["name"].Value;
                var value = attribute.Groups["value"];
                if (name.Equals("Include", StringComparison.OrdinalIgnoreCase) ||
                    name.Equals("Update", StringComparison.OrdinalIgnoreCase))
                {
                    isPackage |= string.Equals(value.Value.Trim(), packageName, StringComparison.OrdinalIgnoreCase);
                }
                else if (name.Equals("Version", StringComparison.OrdinalIgnoreCase) && versionAttr == null)
                {
                    versionAttr = value;
                }
                else if (allowVersionOverride && name.Equals("VersionOverride", StringComparison.OrdinalIgnoreCase) && overrideAttr == null)
                {
                    overrideAttr = value;
                }
            }

            version = overrideAttr ?? versionAttr;
            return isPackage;
        }

        private static Regex PropertyElementPattern(string propertyName) => new(
            InactiveMarkupPattern +
            @"|(?<open><(?<tag>" + Regex.Escape(propertyName) + @")(?<attributes>(?:\s+" + AttributePattern + @")*)\s*>)(?<value>[\s\S]*?)(?<close></\k<tag>\s*>)" +
            @"|(?<empty><(?<etag>" + Regex.Escape(propertyName) + @")(?<eattributes>(?:\s+" + AttributePattern + @")*)\s*/>)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        /// <summary>
        /// Replaces the value of the <paramref name="elementIndex"/>-th (zero-based, document order)
        /// <paramref name="propertyName"/> element directly inside a <c>&lt;PropertyGroup&gt;</c>, preserving its
        /// attributes, tag casing and surrounding whitespace. Other definitions of the property are left alone.
        /// </summary>
        public static string ReplacePropertyValueAt(string content, string propertyName, int elementIndex, string newValue)
        {
            var propertyPattern = PropertyElementPattern(propertyName);
            var index = 0;

            return PropertyGroupPattern.Replace(
                content,
                groupMatch =>
                {
                    if (!groupMatch.Groups["open"].Success)
                    {
                        return groupMatch.Value;
                    }

                    var newBody = propertyPattern.Replace(
                        groupMatch.Groups["body"].Value,
                        propMatch =>
                        {
                            if (!propMatch.Groups["open"].Success && !propMatch.Groups["empty"].Success)
                            {
                                return propMatch.Value;
                            }

                            if (index++ != elementIndex)
                            {
                                return propMatch.Value;
                            }

                            return propMatch.Groups["open"].Success
                                ? propMatch.Groups["open"].Value + ReplaceTrimmed(propMatch.Groups["value"].Value, newValue) + propMatch.Groups["close"].Value
                                : $"<{propMatch.Groups["etag"].Value}{propMatch.Groups["eattributes"].Value}>{newValue}</{propMatch.Groups["etag"].Value}>";
                        });

                    return groupMatch.Groups["open"].Value + newBody + groupMatch.Groups["close"].Value;
                });
        }

        /// <summary>
        /// Inserts <c>&lt;propertyName&gt;newValue&lt;/propertyName&gt;</c> at the end of the
        /// <paramref name="propertyGroupIndex"/>-th (zero-based, document order, non-empty) <c>&lt;PropertyGroup&gt;</c>,
        /// or, when the index is negative, in a new <c>&lt;PropertyGroup&gt;</c> at the start of <c>&lt;Project&gt;</c>.
        /// </summary>
        public static string InsertProperty(string content, int propertyGroupIndex, string propertyName, string newValue)
        {
            var newline = content.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
            var inserted = false;

            if (propertyGroupIndex >= 0)
            {
                var index = 0;
                var withPropertyGroup = PropertyGroupPattern.Replace(
                    content,
                    m =>
                    {
                        if (!m.Groups["open"].Success || index++ != propertyGroupIndex)
                        {
                            return m.Value;
                        }

                        inserted = true;
                        var body = m.Groups["body"].Value;
                        var lastLf = body.LastIndexOf('\n');
                        if (lastLf < 0)
                        {
                            return $"{m.Groups["open"].Value}{body}<{propertyName}>{newValue}</{propertyName}>{m.Groups["close"].Value}";
                        }

                        var prefix = body[..(lastLf > 0 && body[lastLf - 1] == '\r' ? lastLf - 1 : lastLf)];
                        var closingIndent = body[(lastLf + 1)..];
                        var prevLf = prefix.LastIndexOf('\n');
                        var prevLine = prevLf >= 0 ? prefix[(prevLf + 1)..] : string.Empty;
                        var childIndent = prevLine[..(prevLine.Length - prevLine.AsSpan().TrimStart().Length)];
                        if (childIndent.Length == 0)
                        {
                            childIndent = closingIndent + (closingIndent.Contains('\t', StringComparison.Ordinal) ? "\t" : "  ");
                        }

                        return $"{m.Groups["open"].Value}{prefix}{newline}{childIndent}<{propertyName}>{newValue}</{propertyName}>{newline}{closingIndent}{m.Groups["close"].Value}";
                    });

                if (inserted)
                {
                    return withPropertyGroup;
                }
            }

            return ProjectOpenTagPattern.Replace(
                content,
                m =>
                {
                    if (inserted || !m.Groups["open"].Success)
                    {
                        return m.Value;
                    }

                    inserted = true;
                    var after = m.Index + m.Length;
                    return after < content.Length && content[after] is '\r' or '\n'
                        ? $"{m.Value}{newline}  <PropertyGroup>{newline}    <{propertyName}>{newValue}</{propertyName}>{newline}  </PropertyGroup>"
                        : $"{m.Value}<PropertyGroup><{propertyName}>{newValue}</{propertyName}></PropertyGroup>";
                });
        }

        /// <summary>
        /// Inserts <c>&lt;propertyName&gt;newValue&lt;/propertyName&gt;</c> immediately before the
        /// <paramref name="anchorIndex"/>-th <paramref name="anchorName"/> property element (see
        /// <see cref="ReplacePropertyValueAt"/>), on its own line with the same indentation when the anchor starts a line.
        /// Returns <paramref name="content"/> unchanged when the anchor isn't found.
        /// </summary>
        public static string InsertPropertyBefore(string content, string anchorName, int anchorIndex, string propertyName, string newValue)
        {
            var newline = content.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
            var anchorPattern = PropertyElementPattern(anchorName);
            var index = 0;

            return PropertyGroupPattern.Replace(
                content,
                groupMatch =>
                {
                    if (!groupMatch.Groups["open"].Success)
                    {
                        return groupMatch.Value;
                    }

                    var body = groupMatch.Groups["body"].Value;
                    var newBody = anchorPattern.Replace(
                        body,
                        propMatch =>
                        {
                            if ((!propMatch.Groups["open"].Success && !propMatch.Groups["empty"].Success) || index++ != anchorIndex)
                            {
                                return propMatch.Value;
                            }

                            var lineStart = body.LastIndexOf('\n', Math.Max(propMatch.Index - 1, 0)) + 1;
                            var leading = body[lineStart..propMatch.Index];
                            var element = $"<{propertyName}>{newValue}</{propertyName}>";
                            return lineStart > 0 && string.IsNullOrWhiteSpace(leading)
                                ? $"{element}{newline}{leading}{propMatch.Value}"
                                : $"{element}{propMatch.Value}";
                        });

                    return groupMatch.Groups["open"].Value + newBody + groupMatch.Groups["close"].Value;
                });
        }

        private static string ReplaceTrimmed(string value, string newValue)
        {
            var span = value.AsSpan();
            var lead = span.Length - span.TrimStart().Length;
            var trail = span.Length - span.TrimEnd().Length;
            return lead + trail >= span.Length
                ? newValue
                : string.Concat(span[..lead], newValue, span[(span.Length - trail)..]);
        }
    }
}

using DotNetOutdated.Core;
using DotNetOutdated.Core.Models;
using NuGet.Common;
using NuGet.Configuration;
using NuGet.Frameworks;
using NuGet.Packaging.Core;
using NuGet.ProjectModel;
using NuGet.Protocol;
using NuGet.Versioning;
using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Abstractions;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace DotNetOutdated.Core.Services
{
    internal class ProjectAnalysisService : IProjectAnalysisService
    {
        private readonly IProjectEvaluator _evaluator;
        private readonly IDotNetRestoreService _dotNetRestoreService;
        private readonly IFileSystem _fileSystem;
        private readonly FileBasedAppDirectives _fileBasedAppDirectives;
        private readonly ILogger _logger;

        // Limits the concurrent `dotnet msbuild` evaluations for SDK-injected package references across all projects
        // being analyzed, since several projects can be analyzed at the same time.
        private readonly SemaphoreSlim _evaluationThrottle = new(Environment.ProcessorCount);

        public ProjectAnalysisService(
            IDependencyGraphService dependencyGraphService,
            IDotNetRestoreService dotNetRestoreService,
            IFileSystem fileSystem)
            : this(dependencyGraphService, dotNetRestoreService, fileSystem, NullLogger.Instance)
        {
        }

        public ProjectAnalysisService(
            IDependencyGraphService dependencyGraphService,
            IDotNetRestoreService dotNetRestoreService,
            IFileSystem fileSystem,
            ILogger logger)
            : this(new DotNetProjectEvaluator(dependencyGraphService, fileSystem), dotNetRestoreService, fileSystem, logger)
        {
        }

        internal ProjectAnalysisService(
            IProjectEvaluator evaluator,
            IDotNetRestoreService dotNetRestoreService,
            IFileSystem fileSystem,
            ILogger logger)
        {
            _evaluator = evaluator;
            _dotNetRestoreService = dotNetRestoreService;
            _fileSystem = fileSystem;
            _fileBasedAppDirectives = new FileBasedAppDirectives(fileSystem, evaluator);
            _logger = logger;
        }

        public async Task<IReadOnlyList<Project>> AnalyzeProjectAsync(string projectPath, ProjectAnalysisOptions? options = null, CancellationToken cancellationToken = default)
        {
            options ??= ProjectAnalysisOptions.Default;
            var runtime = options.Runtime;

            // Generating the restore graph runs `dotnet msbuild` to completion, so don't start it for a cancelled request.
            cancellationToken.ThrowIfCancellationRequested();
            var dependencyGraph = await _evaluator.GetRestoreGraphAsync(projectPath, runtime).ConfigureAwait(false);

            var isFileBasedApp = projectPath.IsCSharpFile();
            var fileBasedAppPath = isFileBasedApp ? _fileSystem.Path.GetFullPath(projectPath) : null;
            var projects = new List<(Project Project, List<TargetFrameworkBuilder> TargetFrameworks)>();
            var sdkEvaluations = new List<SdkEvaluation>();
            foreach (var packageSpec in dependencyGraph.Projects.Where(p => p.RestoreMetadata.ProjectStyle == ProjectStyle.PackageReference))
            {
                var analyzedProjectPath = fileBasedAppPath ?? packageSpec.FilePath!;

                // Restore the packages
                cancellationToken.ThrowIfCancellationRequested();

                if (options.RunRestore)
                {
                    _dotNetRestoreService.Restore(analyzedProjectPath);
                }

                // Load the lock file
                string lockFilePath = _fileSystem.Path.Combine(packageSpec.RestoreMetadata.OutputPath, "project.assets.json");
                var lockFile = LockFileUtilities.GetLockFile(lockFilePath, _logger);
                if (lockFile == null)
                    throw new InvalidOperationException($"Could not load lock file '{lockFilePath}' for project '{analyzedProjectPath}'. The file may be missing, unreadable, or in an unsupported format. Try running 'dotnet restore' on the project.");

                // Create a project
                var projectName = isFileBasedApp ? _fileSystem.Path.GetFileName(projectPath) : packageSpec.Name;
                var project = new Project
                {
                    Name = projectName,
                    FilePath = analyzedProjectPath,
                    Sources = packageSpec.RestoreMetadata.Sources.Select(s => s.SourceUri).ToList(),
                    Version = packageSpec.Version,
                };
                var targetFrameworks = new List<TargetFrameworkBuilder>();
                projects.Add((project, targetFrameworks));

                var projectSdkReferences = isFileBasedApp
                    ? []
                    : ProjectSdkReferenceHelper.Discover(_fileSystem, analyzedProjectPath);
                var packageFolders = !isFileBasedApp && SdkInjectedPackageReferences.UsesCustomSdk(_fileSystem, analyzedProjectPath)
                    ? GetPackageFolders(analyzedProjectPath, packageSpec)
                    : null;

                // Get the target frameworks with their dependencies
                foreach (var targetFrameworkInformation in packageSpec.TargetFrameworks)
                {
                    var targetFramework = new TargetFrameworkBuilder(targetFrameworkInformation.FrameworkName, targetFrameworkInformation.TargetAlias);
                    targetFrameworks.Add(targetFramework);

                    var target = lockFile.Targets.FirstOrDefault(t => t.TargetFramework.Equals(targetFrameworkInformation.FrameworkName));

                    if (target != null)
                    {
                        foreach (var projectDependency in targetFrameworkInformation.Dependencies)
                        {
                            var projectLibrary = target.Libraries.FirstOrDefault(library => string.Equals(library.Name, projectDependency.Name, StringComparison.OrdinalIgnoreCase));

                            bool isDevelopmentDependency = false;
                            if (projectLibrary != null)
                            {
                                // Determine whether this is a development dependency
                                var packageIdentity = new PackageIdentity(projectLibrary.Name!, projectLibrary.Version);
                                var packageInfo = LocalFolderUtility.GetPackageV3(packageSpec.RestoreMetadata.PackagesPath, packageIdentity, NullLogger.Instance);
                                if (packageInfo != null)
                                    isDevelopmentDependency = packageInfo.GetReader().GetDevelopmentDependency();
                            }

                            targetFramework.TryAdd(new Dependency
                            {
                                Name = projectDependency.Name,
                                VersionRange = projectDependency.LibraryRange.VersionRange!,
                                ResolvedVersion = projectLibrary?.Version,
                                IsAutoReferenced = projectDependency.AutoReferenced,
                                IsDevelopmentDependency = isDevelopmentDependency,
                            });

                            // Process transitive dependencies for the library
                            if (options.IncludeTransitiveDependencies)
                                AddDependencies(targetFramework, projectLibrary, target, 1, options.TransitiveDepth);
                        }

                        if (isFileBasedApp)
                        {
                            // Use the normalized full path so directive discovery (and its cache) keys off the
                            // same path used for restore and asset loading, even when the caller passed a relative path.
                            ApplyFileBasedAppDirectives(analyzedProjectPath, targetFramework);
                        }

                        foreach (var sdkReference in projectSdkReferences)
                        {
                            targetFramework.Set(new Dependency
                            {
                                Name = sdkReference.Name,
                                VersionRange = sdkReference.VersionRange,
                                ResolvedVersion = sdkReference.ResolvedVersion,
                                Kind = ReferenceKind.Sdk,
                            });
                        }

                        if (packageFolders != null)
                        {
                            sdkEvaluations.Add(new SdkEvaluation(analyzedProjectPath, targetFrameworkInformation.TargetAlias, runtime, packageFolders, targetFramework));
                        }
                    }
                }
            }

            // Each evaluation is a separate `dotnet msbuild` process, so run them side by side.
            await Task.WhenAll(sdkEvaluations.Select(evaluation => MarkPackageDefinedReferencesAsAutoReferencedAsync(evaluation, cancellationToken))).ConfigureAwait(false);

            return projects
                .Select(pair => pair.Project with { TargetFrameworks = pair.TargetFrameworks.Select(builder => builder.Build()).ToList() })
                .ToList();
        }

        private void ApplyFileBasedAppDirectives(string projectPath, TargetFrameworkBuilder targetFramework)
        {
            var fileBasedReferences = _fileBasedAppDirectives.References(projectPath);
            if (fileBasedReferences.Count == 0)
            {
                return;
            }

            // The directives are the authoritative source of direct dependencies for a file-based app: replace every
            // non-transitive graph dependency with the directive references.
            targetFramework.RemoveDirectDependencies();

            foreach (var reference in fileBasedReferences)
            {
                targetFramework.Set(new Dependency
                {
                    Name = reference.Name,
                    VersionRange = reference.VersionRange,
                    ResolvedVersion = reference.ResolvedVersion,
                    Kind = reference.Kind,
                });
            }
        }

        /// <summary>
        /// Marks direct dependencies as auto-referenced when every <c>PackageReference</c> item for them is defined inside
        /// a NuGet package, such as the props or targets of an SDK like <c>Cake.Sdk</c> or <c>MSTest.Sdk</c>.
        /// </summary>
        private async Task MarkPackageDefinedReferencesAsAutoReferencedAsync(SdkEvaluation evaluation, CancellationToken cancellationToken)
        {
            await _evaluationThrottle.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
                var items = await Task.Run(() => _evaluator.GetPackageReferenceItems(evaluation.ProjectPath, evaluation.TargetAlias, evaluation.Runtime), cancellationToken).ConfigureAwait(false);
                if (items == null)
                {
                    _logger.LogVerbose($"Could not evaluate the package references of '{evaluation.ProjectPath}' for {evaluation.TargetAlias}. " +
                        "Packages that its SDK adds are reported as direct dependencies.");
                    return;
                }

                var packageDefinedNames = SdkInjectedPackageReferences.GetPackageDefinedNames(_fileSystem, items, evaluation.PackageFolders);
                evaluation.TargetFramework.ReplaceAll(
                    SdkInjectedPackageReferences.MarkAsAutoReferenced(evaluation.TargetFramework.Dependencies, packageDefinedNames));
            }
            finally
            {
                _evaluationThrottle.Release();
            }
        }

        private List<string?> GetPackageFolders(string projectPath, PackageSpec packageSpec) =>
            // The SDK resolver finds SDKs in the global packages folder from the NuGet settings, while restore uses
            // RestorePackagesPath when it is set, so check both.
            new[] { packageSpec.RestoreMetadata.PackagesPath, GetConfiguredGlobalPackagesFolder(projectPath) }
                .Concat(packageSpec.RestoreMetadata.FallbackFolders ?? [])
                .ToList();

        private string? GetConfiguredGlobalPackagesFolder(string projectPath)
        {
            try
            {
                var settings = Settings.LoadDefaultSettings(_fileSystem.Path.GetDirectoryName(projectPath));
                return SettingsUtility.GetGlobalPackagesFolder(settings);
            }
            catch (Exception ex) when (ex is NuGetConfigurationException or IOException or UnauthorizedAccessException)
            {
                _logger.LogVerbose($"Could not read the NuGet global packages folder for '{projectPath}': {ex.Message}");
                return null;
            }
        }

        private sealed record SdkEvaluation(string ProjectPath, string TargetAlias, string? Runtime, List<string?> PackageFolders, TargetFrameworkBuilder TargetFramework);

        /// <summary>
        /// The dependencies of a target framework while its project is analyzed, keyed by name and kind, since a project
        /// can reference a package and an SDK with the same id.
        /// </summary>
        private sealed class TargetFrameworkBuilder(NuGetFramework name, string? targetAlias)
        {
            private readonly Dictionary<(string Name, ReferenceKind Kind), Dependency> _dependencies = [];

            public IReadOnlyList<Dependency> Dependencies => [.. _dependencies.Values];

            public bool ContainsPackage(string name) => _dependencies.ContainsKey((name, ReferenceKind.Package));

            public void TryAdd(Dependency dependency) => _dependencies.TryAdd((dependency.Name, dependency.Kind), dependency);

            public void Set(Dependency dependency) => _dependencies[(dependency.Name, dependency.Kind)] = dependency;

            public void RemoveDirectDependencies()
            {
                foreach (var key in _dependencies.Where(pair => !pair.Value.IsTransitive).Select(pair => pair.Key).ToList())
                {
                    _dependencies.Remove(key);
                }
            }

            public void ReplaceAll(IEnumerable<Dependency> dependencies)
            {
                _dependencies.Clear();
                foreach (var dependency in dependencies)
                {
                    Set(dependency);
                }
            }

            public TargetFramework Build() => new() { Name = name, TargetAlias = targetAlias, Dependencies = Dependencies };
        }

        private void AddDependencies(TargetFrameworkBuilder targetFramework, LockFileTargetLibrary? parentLibrary, LockFileTarget target, int level, int transitiveDepth)
        {
            if (parentLibrary?.Dependencies != null)
            {
                foreach (var packageDependency in parentLibrary.Dependencies)
                {
                    var childLibrary = target.Libraries.FirstOrDefault(library => string.Equals(library.Name, packageDependency.Id, StringComparison.OrdinalIgnoreCase));

                    // Only add library and process child dependencies if we have not come across this dependency before
                    if (!targetFramework.ContainsPackage(packageDependency.Id))
                    {
                        targetFramework.TryAdd(new Dependency
                        {
                            Name = packageDependency.Id,
                            VersionRange = packageDependency.VersionRange,
                            ResolvedVersion = childLibrary?.Version,
                            IsTransitive = true,
                        });

                        // Process the dependency for this project dependency
                        if (level < transitiveDepth)
                            AddDependencies(targetFramework, childLibrary, target, level + 1, transitiveDepth);
                    }
                }
            }
        }
    }
}

using DotNetOutdated.Core;
using DotNetOutdated.Core.Exceptions;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Abstractions;
using System.Linq;

namespace DotNetOutdated.Core.Services
{
    internal sealed class ProjectDiscoveryService : IProjectDiscoveryService
    {
        private readonly IFileSystem _fileSystem;

        public ProjectDiscoveryService(IFileSystem fileSystem)
        {
            _fileSystem = fileSystem;
        }

        public IList<string> DiscoverProjects(string path, bool recursive = false, bool includeFileBasedApps = false)
        {
            if (!(_fileSystem.File.Exists(path) || _fileSystem.Directory.Exists(path)))
                throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryOrFileDoesNotExist, path));

            var fileAttributes = _fileSystem.File.GetAttributes(path);

            // If a directory was passed in, search for a .sln or .csproj file
            if (fileAttributes.HasFlag(FileAttributes.Directory))
            {
                // If we are in recursive mode, find all individual projects recursively
                if (recursive)
                {
                    string[] recursiveProjectFiles;
                    if (includeFileBasedApps)
                    {
                        var recursiveDiscoveryResult = DiscoverRecursiveProjectFiles(path, isInProjectCone: false);
                        recursiveProjectFiles = recursiveDiscoveryResult.ProjectFiles
                            .Concat(recursiveDiscoveryResult.FileBasedApps)
                            .ToArray();
                    }
                    else
                    {
                        recursiveProjectFiles = _fileSystem.Directory.GetFiles(path, "*.csproj", SearchOption.AllDirectories)
                            .Concat(_fileSystem.Directory.GetFiles(path, "*.fsproj", SearchOption.AllDirectories))
                            .ToArray();
                    }

                    if (recursiveProjectFiles.Length > 0)
                        return recursiveProjectFiles;

                    // At this point the path contains no solutions or projects, so throw an exception
                    throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryDoesNotContainSolutionsOrProjects, path));
                }

                // Search for solution(s)
                var solutionFiles = _fileSystem.Directory.GetFiles(path, "*.sln");
                if (solutionFiles.Length == 1)
                    return new[] { _fileSystem.Path.GetFullPath(solutionFiles[0]) };

                if (solutionFiles.Length > 1)
                    throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryContainsMultipleSolutions, path));

                solutionFiles = _fileSystem.Directory.GetFiles(path, "*.slnx");
                if (solutionFiles.Length == 1)
                    return new[] { _fileSystem.Path.GetFullPath(solutionFiles[0]) };

                if (solutionFiles.Length > 1)
                    throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryContainsMultipleSolutions, path));

                // We did not find any solutions, so try and find individual projects
                var projectFiles = _fileSystem.Directory.GetFiles(path, "*.csproj").Concat(_fileSystem.Directory.GetFiles(path, "*.fsproj")).ToArray();
                if (projectFiles.Length == 1)
                    return new[] { _fileSystem.Path.GetFullPath(projectFiles[0]) };

                if (projectFiles.Length > 1)
                    throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryContainsMultipleProjects, path));

                // At this point the path contains no solutions or projects, so throw an exception
                throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.DirectoryDoesNotContainSolutionsOrProjects, path));
            }

            // If a solution file or project file was passed, just return that
            if (path.IsSolutionFile() || path.IsProjectFile() || path.IsCSharpFile())
            {
                return new[] { _fileSystem.Path.GetFullPath(path) };
            }

            // At this point, we know the file passed in is not a valid project or solution
            throw new CommandValidationException(string.Format(CultureInfo.InvariantCulture, Resources.ValidationErrorMessages.FileNotAValidSolutionOrProject, path));
        }

        private RecursiveDiscoveryResult DiscoverRecursiveProjectFiles(string path, bool isInProjectCone)
        {
            var result = new RecursiveDiscoveryResult();
            var files = _fileSystem.Directory.GetFiles(path, "*", SearchOption.TopDirectoryOnly);
            var directoryContainsCSharpProject = false;

            foreach (var file in files)
            {
                if (file.IsCSharpProjectFile())
                {
                    result.ProjectFiles.Add(file);
                    directoryContainsCSharpProject = true;
                    continue;
                }

                if (file.IsProjectFile())
                {
                    result.ProjectFiles.Add(file);
                }
            }

            var currentDirectoryIsInProjectCone = isInProjectCone || directoryContainsCSharpProject;
            if (!currentDirectoryIsInProjectCone)
            {
                foreach (var file in files)
                {
                    if (file.IsCSharpFile() && StartsWithShebang(file))
                    {
                        result.FileBasedApps.Add(file);
                    }
                }
            }

            var childResults = _fileSystem.Directory.GetDirectories(path, "*", SearchOption.TopDirectoryOnly)
                .Select(directory => DiscoverRecursiveProjectFiles(directory, currentDirectoryIsInProjectCone))
                .ToArray();

            foreach (var childResult in childResults)
            {
                result.ProjectFiles.AddRange(childResult.ProjectFiles);
                result.FileBasedApps.AddRange(childResult.FileBasedApps);
            }

            return result;
        }

        private bool StartsWithShebang(string file)
        {
            using var stream = _fileSystem.File.OpenRead(file);
            Span<byte> bytes = stackalloc byte[5];
            var bytesRead = stream.Read(bytes);
            // Allow scripts saved with a UTF-8 BOM before the shebang.
            var offset = bytesRead >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF ? 3 : 0;

            return bytesRead - offset >= 2 && bytes[offset] == (byte)'#' && bytes[offset + 1] == (byte)'!';
        }

        private sealed class RecursiveDiscoveryResult
        {
            public List<string> ProjectFiles { get; } = new();

            public List<string> FileBasedApps { get; } = new();
        }
    }
}

using NuGet.Versioning;
using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Abstractions;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;

#nullable enable

namespace DotNetOutdated.Core.Services;

/// <summary>
/// A versioned MSBuild project SDK declared in a project file as <c>&lt;Project Sdk="Id/Version"&gt;</c>,
/// <c>&lt;Sdk Name="Id" Version="Version" /&gt;</c> or <c>&lt;Import Project="..." Sdk="Id" Version="Version" /&gt;</c>.
/// </summary>
internal sealed class ProjectSdkReference
{
    /// <summary>
    /// Gets the SDK package id.
    /// </summary>
    public string Name { get; init; } = string.Empty;

    /// <summary>
    /// Gets the version declared in the project file.
    /// </summary>
    public required NuGetVersion ResolvedVersion { get; init; }

    /// <summary>
    /// Gets the version range used when resolving the latest version on NuGet feeds. The declared version is the
    /// inclusive floor with an open upper bound so newer versions can be discovered.
    /// </summary>
    public required VersionRange VersionRange { get; init; }
}

/// <summary>
/// Where an MSBuild project SDK is declared in a project file.
/// </summary>
internal enum ProjectSdkDeclarationKind
{
    /// <summary><c>&lt;Project Sdk="Id[/Version]"&gt;</c>. One declaration per SDK in the semicolon-separated list.</summary>
    ProjectAttribute,

    /// <summary><c>&lt;Sdk Name="Id" Version="Version" /&gt;</c>.</summary>
    SdkElement,

    /// <summary><c>&lt;Import Project="Sdk.props" Sdk="Id" Version="Version" /&gt;</c>.</summary>
    ImportElement
}

/// <summary>
/// An MSBuild project SDK declared in a project file, as written. <see cref="Version"/> is <see langword="null"/> when
/// the declaration has no version, and may contain MSBuild property references such as <c>$(AspireVersion)</c>.
/// </summary>
internal sealed record ProjectSdkDeclaration(string Name, string? Version, ProjectSdkDeclarationKind Kind);

/// <summary>
/// Discovers and updates versioned MSBuild project SDK references in project files.
/// Only literal versions in the project file itself are supported; SDK versions pinned via
/// <c>global.json</c> <c>msbuild-sdks</c>, MSBuild properties or imported files are ignored.
/// Discovery parses the file as XML. Updates edit the text in place so the rest of the file keeps its formatting.
/// </summary>
internal static partial class ProjectSdkReferenceHelper
{
    // A <Project>, <Sdk> or <Import> start tag. Quoted attribute values are consumed whole, so a '>' inside a
    // value such as Condition="'$(A)' > '0'" does not end the tag.
    [GeneratedRegex(@"<(Project|Sdk|Import)\b((?:[^>""']|""[^""]*""|'[^']*')*)>")]
    private static partial Regex SdkDeclarationTagRegex();

    [GeneratedRegex(@"([\w:.-]+)\s*=\s*(""[^""]*""|'[^']*')")]
    private static partial Regex AttributeRegex();

    // Text that cannot hold an SDK declaration: comments, CDATA and the free-form <ProjectExtensions> section.
    [GeneratedRegex(@"<!--.*?-->|<!\[CDATA\[.*?\]\]>|<ProjectExtensions\b(?:[^>""']|""[^""]*""|'[^']*')*?/>|<ProjectExtensions\b.*?</ProjectExtensions\s*>", RegexOptions.Singleline)]
    private static partial Regex NonDeclarationTextRegex();

    /// <summary>
    /// Reads every MSBuild project SDK declared in a project file: the <c>Sdk</c> attribute of the root
    /// <c>&lt;Project&gt;</c>, <c>&lt;Sdk&gt;</c> elements and <c>&lt;Import Sdk="..."&gt;</c> elements, versioned or not.
    /// The file is parsed as XML, so SDKs inside comments are ignored, as is anything inside <c>&lt;ProjectExtensions&gt;</c>.
    /// </summary>
    /// <returns>The declarations in document order, or an empty list when the file is missing, unreadable or not valid XML.</returns>
    public static IReadOnlyList<ProjectSdkDeclaration> GetDeclarations(IFileSystem fileSystem, string projectFilePath)
    {
        XElement? root;
        try
        {
            if (!fileSystem.File.Exists(projectFilePath))
            {
                return [];
            }

            root = XDocument.Parse(fileSystem.File.ReadAllText(projectFilePath)).Root;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or XmlException)
        {
            return [];
        }

        if (root == null || root.Name.LocalName != "Project")
        {
            return [];
        }

        var declarations = new List<ProjectSdkDeclaration>();

        foreach (var sdk in (root.Attribute("Sdk")?.Value ?? string.Empty).Split(';'))
        {
            var separatorIndex = sdk.IndexOf('/');
            var name = (separatorIndex >= 0 ? sdk[..separatorIndex] : sdk).Trim();
            if (name.Length > 0)
            {
                declarations.Add(new ProjectSdkDeclaration(
                    name,
                    separatorIndex >= 0 ? sdk[(separatorIndex + 1)..].Trim() : null,
                    ProjectSdkDeclarationKind.ProjectAttribute));
            }
        }

        // <ProjectExtensions> holds arbitrary XML that MSBuild ignores, so skip anything inside it.
        foreach (var element in root.Descendants().Where(element => !element.AncestorsAndSelf().Any(ancestor => ancestor.Name.LocalName == "ProjectExtensions")))
        {
            var kind = element.Name.LocalName switch
            {
                "Sdk" when element.Parent == root => ProjectSdkDeclarationKind.SdkElement,
                "Import" => ProjectSdkDeclarationKind.ImportElement,
                _ => (ProjectSdkDeclarationKind?)null
            };

            var name = kind == ProjectSdkDeclarationKind.SdkElement
                ? element.Attribute("Name")?.Value.Trim()
                : element.Attribute("Sdk")?.Value.Trim();

            if (kind != null && !string.IsNullOrEmpty(name))
            {
                declarations.Add(new ProjectSdkDeclaration(name, element.Attribute("Version")?.Value.Trim(), kind.Value));
            }
        }

        return declarations;
    }

    /// <summary>
    /// Discovers the versioned SDK references declared in a project file. Only literal versions are returned;
    /// unversioned and property-backed declarations are skipped.
    /// </summary>
    public static IReadOnlyList<ProjectSdkReference> Discover(IFileSystem fileSystem, string projectFilePath)
    {
        var references = new List<ProjectSdkReference>();

        foreach (var declaration in GetDeclarations(fileSystem, projectFilePath))
        {
            if (declaration.Version != null)
            {
                TryAdd(references, declaration.Name, declaration.Version);
            }
        }

        return references;
    }

    /// <summary>
    /// Updates the version of every declaration of the named SDK in a project file. Text inside XML comments, CDATA
    /// sections and <c>&lt;ProjectExtensions&gt;</c> is left alone, matching what <see cref="GetDeclarations"/> reads.
    /// </summary>
    /// <returns><see langword="true"/> when the project file was changed; otherwise <see langword="false"/>.</returns>
    public static bool TryUpdate(IFileSystem fileSystem, string projectFilePath, string name, NuGetVersion newVersion)
    {
        var content = ReadAllText(fileSystem, projectFilePath, out var encoding);

        // Match against a copy where comments, CDATA and <ProjectExtensions> are blanked out with spaces. The copy has
        // the same length as the original, so every match index is also an index into the original content.
        var searchable = NonDeclarationTextRegex().Replace(content, match => new string(' ', match.Length));
        var edits = new List<(int Index, int Length, string Value)>();

        var seenProject = false;
        foreach (Match tag in SdkDeclarationTagRegex().Matches(searchable))
        {
            var attributes = GetAttributes(tag.Groups[2]);
            switch (tag.Groups[1].Value)
            {
                // Only the root <Project> declares SDKs; skip any later tag with the same name.
                case "Project" when !seenProject:
                    seenProject = true;
                    if (attributes.TryGetValue("Sdk", out var quotedValue))
                    {
                        var sdks = Unquote(quotedValue.Value).Split(';').Select(sdk =>
                        {
                            var separatorIndex = sdk.IndexOf('/');
                            return separatorIndex > 0 && IsLiteralMatch(sdk[..separatorIndex], sdk[(separatorIndex + 1)..], name)
                                ? $"{sdk[..(separatorIndex + 1)]}{newVersion}"
                                : sdk;
                        });

                        edits.Add((quotedValue.Index, quotedValue.Length, $"{quotedValue.Value[0]}{string.Join(';', sdks)}{quotedValue.Value[0]}"));
                    }

                    break;

                // <Sdk Name="Id" Version="..." /> and <Import Project="Sdk.props" Sdk="Id" Version="..." />
                case "Sdk" or "Import":
                    var nameAttribute = tag.Groups[1].Value == "Sdk" ? "Name" : "Sdk";
                    if (attributes.TryGetValue(nameAttribute, out var quotedName) &&
                        attributes.TryGetValue("Version", out var quotedVersion) &&
                        IsLiteralMatch(Unquote(quotedName.Value), Unquote(quotedVersion.Value), name))
                    {
                        edits.Add((quotedVersion.Index, quotedVersion.Length, $"{quotedVersion.Value[0]}{newVersion}{quotedVersion.Value[0]}"));
                    }

                    break;
            }
        }

        var newContent = new StringBuilder(content);
        foreach (var (index, length, value) in edits.OrderByDescending(edit => edit.Index))
        {
            newContent.Remove(index, length).Insert(index, value);
        }

        if (string.Equals(content, newContent.ToString(), StringComparison.Ordinal))
        {
            return false;
        }

        fileSystem.File.WriteAllText(projectFilePath, newContent.ToString(), encoding);
        return true;
    }

    /// <summary>
    /// Gets the quoted values of the attributes in a start tag, keyed by attribute name. Each value's index is an index
    /// into the text the tag was matched in.
    /// </summary>
    private static Dictionary<string, (int Index, int Length, string Value)> GetAttributes(Group attributesText)
    {
        var attributes = new Dictionary<string, (int Index, int Length, string Value)>(StringComparer.Ordinal);
        foreach (Match attribute in AttributeRegex().Matches(attributesText.Value))
        {
            var value = attribute.Groups[2];
            attributes.TryAdd(attribute.Groups[1].Value, (attributesText.Index + value.Index, value.Length, value.Value));
        }

        return attributes;
    }

    /// <summary>
    /// Reads a text file and reports its encoding, so it can be written back with the same byte order mark.
    /// Files without a byte order mark are read and written as UTF-8 without one.
    /// </summary>
    private static string ReadAllText(IFileSystem fileSystem, string path, out Encoding encoding)
    {
        using var reader = new StreamReader(
            new MemoryStream(fileSystem.File.ReadAllBytes(path)),
            new UTF8Encoding(encoderShouldEmitUTF8Identifier: false),
            detectEncodingFromByteOrderMarks: true);

        var content = reader.ReadToEnd();
        encoding = reader.CurrentEncoding;
        return content;
    }

    private static void TryAdd(List<ProjectSdkReference> references, string name, string version)
    {
        name = name.Trim();
        version = version.Trim();

        if (name.Length == 0 ||
            FileBasedAppReferenceHelper.ContainsPropertyReference(name, version) ||
            !NuGetVersion.TryParse(version, out var resolvedVersion) ||
            references.Any(reference => string.Equals(reference.Name, name, StringComparison.OrdinalIgnoreCase)))
        {
            return;
        }

        references.Add(new ProjectSdkReference
        {
            Name = name,
            ResolvedVersion = resolvedVersion,
            VersionRange = FileBasedAppReferenceHelper.CreateMinimumVersionRange(resolvedVersion)
        });
    }

    private static bool IsLiteralMatch(string name, string version, string expectedName) =>
        string.Equals(name.Trim(), expectedName, StringComparison.OrdinalIgnoreCase) &&
        NuGetVersion.TryParse(version.Trim(), out _);

    private static string Unquote(string quotedValue) => quotedValue[1..^1];
}

using System.Linq;

namespace DotNetOutdated.Core.Services
{
    public class RunStatus
    {
        /// <summary>The process's standard output; empty when there was none.</summary>
        public string Output { get; }

        /// <summary>The process's standard error; empty when there was none.</summary>
        public string Errors { get; }
        public int ExitCode { get; }

        public bool IsSuccess => ExitCode == 0;

        /// <summary>
        /// The process output followed by its errors, trimmed and with empty parts left out, for explaining a failure.
        /// </summary>
        /// <remarks>
        /// Both streams are needed: <c>dotnet add package</c>, for example, reports NuGet failures (such as a package
        /// whose version is declared in an imported file it cannot edit) on stdout rather than stderr.
        /// </remarks>
        public string FailureDetails => string.Join(
            System.Environment.NewLine,
            new[] { Output.Trim(), Errors.Trim() }.Where(part => !string.IsNullOrEmpty(part)));

        /// <param name="output">The standard output; <see langword="null"/> is treated as empty.</param>
        /// <param name="errors">The standard error; <see langword="null"/> is treated as empty.</param>
        public RunStatus(string? output, string? errors, int exitCode)
        {
            Output = output ?? string.Empty;
            Errors = errors ?? string.Empty;
            ExitCode = exitCode;
        }
    }
}

using DotNetOutdated.Core.Models;
using System;
using System.Collections.Generic;
using System.IO.Abstractions;
using System.Linq;

namespace DotNetOutdated.Core.Services
{
    /// <summary>
    /// Finds package references that an MSBuild SDK or package adds to a project from its own props or targets files,
    /// such as <c>Cake.Generator</c> from <c>Cake.Sdk</c> or the MSTest packages from <c>MSTest.Sdk</c>. Their versions
    /// come from the SDK, so <c>dotnet add package</c> cannot upgrade them in the project.
    /// </summary>
    internal static class SdkInjectedPackageReferences
    {
        // Paths are case-sensitive on Linux, and case-insensitive by default on Windows and macOS.
        private static readonly StringComparison PathComparison = OperatingSystem.IsLinux() ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
        private static readonly StringComparer PathComparer = StringComparer.FromComparison(PathComparison);

        private static readonly string[] DirectoryBuildFileNames = ["Directory.Build.props", "Directory.Build.targets"];

        /// <summary>
        /// Determines whether a project can use an SDK other than the <c>Microsoft.NET.Sdk</c> family. It checks the
        /// project file and every <c>Directory.Build.props</c> and <c>Directory.Build.targets</c> file in the project's
        /// directory and its parents, because a repository can import a custom SDK for all of its projects from there.
        /// </summary>
        /// <remarks>
        /// MSBuild imports only the nearest <c>Directory.Build.*</c> file, which may import the next one up. Checking
        /// every file above the project can only cause an unneeded evaluation, never a missed one. SDKs imported from
        /// other files, such as a custom <c>DirectoryBuildPropsPath</c>, are not detected.
        /// </remarks>
        public static bool UsesCustomSdk(IFileSystem fileSystem, string projectPath)
        {
            if (FileDeclaresCustomSdk(fileSystem, projectPath))
            {
                return true;
            }

            for (var directory = fileSystem.Path.GetDirectoryName(fileSystem.Path.GetFullPath(projectPath));
                 !string.IsNullOrEmpty(directory);
                 directory = fileSystem.Path.GetDirectoryName(directory))
            {
                foreach (var fileName in DirectoryBuildFileNames)
                {
                    var path = fileSystem.Path.Combine(directory, fileName);
                    if (FileDeclaresCustomSdk(fileSystem, path))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        /// <summary>
        /// Determines whether an MSBuild file declares an SDK other than the <c>Microsoft.NET.Sdk</c> family, in the
        /// <c>Sdk</c> attribute of the project, an <c>&lt;Sdk&gt;</c> element or an <c>&lt;Import Sdk&gt;</c>.
        /// Such SDKs are usually resolved from NuGet and can add package references of their own.
        /// </summary>
        /// <returns><c>false</c> when the file is missing, unreadable or not valid XML.</returns>
        private static bool FileDeclaresCustomSdk(IFileSystem fileSystem, string path) =>
            ProjectSdkReferenceHelper.GetDeclarations(fileSystem, path).Any(declaration => IsCustomSdkName(declaration.Name));

        /// <summary>
        /// Determines whether an SDK name is outside the <c>Microsoft.NET.Sdk</c> family, which ships with the .NET SDK
        /// and marks its own package references as implicitly defined.
        /// </summary>
        public static bool IsCustomSdkName(string sdkName) =>
            !string.Equals(sdkName, "Microsoft.NET.Sdk", StringComparison.OrdinalIgnoreCase) &&
            !sdkName.StartsWith("Microsoft.NET.Sdk.", StringComparison.OrdinalIgnoreCase);

        /// <summary>
        /// Returns the names of the packages whose <c>PackageReference</c> items are all defined in a file inside one of
        /// <paramref name="packageFolders"/>. A package with at least one item defined elsewhere, for example in the
        /// project or in a <c>Directory.Build.props</c> file, is referenced by the user and is not returned.
        /// </summary>
        public static HashSet<string> GetPackageDefinedNames(IFileSystem fileSystem, IEnumerable<PackageReferenceItem> items, IEnumerable<string?> packageFolders)
        {
            var folders = packageFolders
                .Where(folder => !string.IsNullOrEmpty(folder))
                .Select(folder => fileSystem.Path.TrimEndingDirectorySeparator(fileSystem.Path.GetFullPath(folder!)) + fileSystem.Path.DirectorySeparatorChar)
                .Distinct(PathComparer)
                .ToList();

            return items
                .Where(item => !string.IsNullOrEmpty(item.Name))
                .GroupBy(item => item.Name!, StringComparer.OrdinalIgnoreCase)
                .Where(group => group.All(item => IsInFolder(fileSystem, item.DefiningProjectFullPath, folders)))
                .Select(group => group.Key)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
        }

        /// <summary>
        /// Marks the direct package dependencies named in <paramref name="packageDefinedNames"/> as auto-referenced.
        /// A declared SDK with the same id as an injected package stays as it is, so its upgrade is still reported.
        /// </summary>
        /// <returns>The dependencies, in the same order, with the named ones marked.</returns>
        public static IReadOnlyList<Dependency> MarkAsAutoReferenced(IEnumerable<Dependency> dependencies, ISet<string> packageDefinedNames) =>
            dependencies
                .Select(dependency =>
                    !dependency.IsTransitive && !dependency.IsAutoReferenced && dependency.Kind == ReferenceKind.Package &&
                    packageDefinedNames.Contains(dependency.Name)
                        ? dependency with { IsAutoReferenced = true }
                        : dependency)
                .ToList();

        private static bool IsInFolder(IFileSystem fileSystem, string? path, List<string> folders) =>
            !string.IsNullOrEmpty(path) &&
            folders.Any(folder => fileSystem.Path.GetFullPath(path).StartsWith(folder, PathComparison));
    }
}

using System.Diagnostics.CodeAnalysis;
using System.Text.RegularExpressions;
using NuGet.Versioning;

namespace DotNetOutdated.Core.Services;

/// <summary>
/// MSBuild version expressions as written in a version attribute or property: <c>$(V)</c>, <c>[$(V), 2.0.0)</c>,
/// or anything else, which can't be updated through its variable.
/// </summary>
internal static partial class VersionExpression
{
    /// <summary>A single <c>$(Name)</c> property reference.</summary>
    [GeneratedRegex(@"\$\(\s*([A-Za-z_][A-Za-z0-9_.-]*)\s*\)")]
    public static partial Regex PropertyReferenceRegex();

    /// <summary>Whether <paramref name="expression"/> contains an MSBuild property reference such as <c>$(Name)</c>.</summary>
    public static bool ContainsPropertyReference(string expression) =>
        !string.IsNullOrEmpty(expression) && expression.Contains("$(");

    /// <summary>Whether <paramref name="expression"/> is exactly one property reference, and if so its name.</summary>
    public static bool TryGetSinglePropertyReference(string expression, out string propertyName)
    {
        propertyName = string.Empty;
        if (string.IsNullOrWhiteSpace(expression))
        {
            return false;
        }

        var trimmed = expression.Trim();
        var match = PropertyReferenceRegex().Match(trimmed);
        if (!match.Success || match.Index != 0 || match.Length != trimmed.Length)
        {
            return false;
        }

        propertyName = match.Groups[1].Value;
        return true;
    }

    // Matches "[ $(Name) , upper ]" style ranges whose lower bound is exactly one property reference.
    private static readonly Regex LowerBoundRangeRegex = new(
        @"^\s*(?<open>[\[(])\s*\$\(\s*(?<name>[A-Za-z_][A-Za-z0-9_.-]*)\s*\)\s*,(?<upper>[^,$\[\]()]*)(?<close>[\])])\s*$",
        RegexOptions.CultureInvariant);

    /// <summary>
    /// Parses the version expressions whose variable can be updated without changing what the expression means:
    /// a single property reference (<c>$(V)</c>) or a range whose lower bound is a property (<c>[$(V), 2.0.0)</c>).
    /// </summary>
    public static bool TryParse(string expression, out string variableName, out bool isRange)
    {
        isRange = false;
        if (TryGetSinglePropertyReference(expression, out variableName))
        {
            return true;
        }

        var match = LowerBoundRangeRegex.Match(expression ?? string.Empty);
        if (!match.Success)
        {
            variableName = string.Empty;
            return false;
        }

        variableName = match.Groups["name"].Value;
        isRange = true;
        return true;
    }

    /// <summary>
    /// Evaluates a supported version expression for a given value of its variable.
    /// </summary>
    public static bool TryEvaluate(string expression, string? variableValue, [NotNullWhen(true)] out VersionRange? range)
    {
        range = null;
        if (!TryParse(expression, out var variableName, out var isRange))
        {
            return false;
        }

        if (!isRange)
        {
            return VersionRange.TryParse(variableValue ?? string.Empty, out range);
        }

        var substituted = PropertyReferenceRegex().Replace(expression, variableValue ?? string.Empty);
        return VersionRange.TryParse(substituted, out range);
    }

    /// <summary>
    /// The expression to write back for <paramref name="newRange"/>: the original when it already evaluates to
    /// the requested range with the variable at its new value, otherwise the requested range with the variable
    /// as its lower bound (so a dropped or changed upper bound is never resurrected).
    /// </summary>
    public static string Compute(string originalExpression, string variableName, VersionRange newRange)
    {
        if (!TryParse(originalExpression, out _, out var isRange) || !isRange)
        {
            return originalExpression;
        }

        if (TryEvaluate(originalExpression, newRange.MinVersion!.ToString(), out var evaluated) &&
            evaluated.Equals(newRange))
        {
            return originalExpression;
        }

        var reference = $"$({variableName})";
        if (newRange.IsPlainVersion())
        {
            return reference;
        }

        var upper = newRange.HasUpperBound ? newRange.MaxVersion.ToNormalizedString() : string.Empty;
        return $"{(newRange.IsMinInclusive ? "[" : "(")}{reference}, {upper}{(newRange.IsMaxInclusive ? "]" : ")")}";
    }
}

using System;
using System.IO.Abstractions;
using System.Linq;

namespace DotNetOutdated.Core.Services;

/// <summary>
/// Where a reference's version is written, which decides how it can be upgraded.
/// </summary>
internal abstract record VersionLocation;

/// <summary>
/// A literal version in the project file or a central <c>Directory.Packages.props</c>, which <c>dotnet add package</c>
/// can rewrite. <see cref="Warning"/> is set when a version expression is replaced by the literal.
/// </summary>
internal sealed record LiteralVersion(string? Warning = null) : VersionLocation;

/// <summary>An MSBuild property behind a <c>PackageReference</c>, <c>PackageVersion</c> or <c>GlobalPackageReference</c>.</summary>
/// <param name="DotNetAddCanUpdate">
/// Whether <c>dotnet add package</c> can rewrite the reference (it can't for a <c>GlobalPackageReference</c>, a
/// <c>VersionOverride</c>, or a <c>PackageReference</c> in an imported file), so the property must be written directly.
/// </param>
internal sealed record MSBuildVariableVersion(PackageVariableInfo Variable, bool DotNetAddCanUpdate) : VersionLocation;

/// <summary>A versioned MSBuild project SDK declared in the project file.</summary>
internal sealed record ProjectSdkVersion(ProjectSdkReference Sdk) : VersionLocation;

/// <summary>A literal <c>#:sdk Id@Version</c> directive in a file-based app.</summary>
internal sealed record FileBasedDirectiveVersion(FileBasedAppReference Reference) : VersionLocation;

/// <summary>A property behind a file-based app's <c>#:package</c> or <c>#:sdk</c> directive.</summary>
internal sealed record FileBasedVariableVersion(PackageVariableInfo Variable) : VersionLocation;

/// <summary>A version that can't be changed automatically; <see cref="Message"/> says why.</summary>
internal sealed record NotEditable(string Message) : VersionLocation;

/// <summary>
/// Finds where the version of a package or SDK referenced by a project is written: in the project, a Directory.*
/// file it imports, an MSBuild property, its <c>Sdk</c> declarations, or the directives of a file-based app.
/// Files are read on every call, so the answer reflects edits made by earlier upgrades.
/// </summary>
internal sealed class VersionLocator(IFileSystem fileSystem, IProjectEvaluator evaluator, FileBasedAppDirectives fileBasedAppDirectives)
{
    private readonly IFileSystem _fileSystem = fileSystem;
    private readonly IProjectEvaluator _evaluator = evaluator;
    private readonly FileBasedAppDirectives _fileBasedAppDirectives = fileBasedAppDirectives;

    /// <param name="kind">
    /// Whether <paramref name="name"/> is a package or an SDK; when <see langword="null"/>, a name the project
    /// declares as an SDK is treated as one.
    /// </param>
    public VersionLocation Locate(string projectPath, string name, ReferenceKind? kind)
    {
        if (projectPath.IsCSharpFile())
        {
            return LocateInFileBasedApp(projectPath, name, kind ?? FileBasedAppReferenceKind(projectPath, name));
        }

        return (kind ?? ProjectReferenceKind(projectPath, name)) == ReferenceKind.Sdk
            ? LocateProjectSdk(projectPath, name)
            : LocatePackage(projectPath, name);
    }

    private ReferenceKind ProjectReferenceKind(string projectPath, string name) =>
        ProjectSdkReferenceHelper.Discover(_fileSystem, projectPath)
            .Any(reference => string.Equals(reference.Name, name, StringComparison.OrdinalIgnoreCase))
            ? ReferenceKind.Sdk
            : ReferenceKind.Package;

    private ReferenceKind FileBasedAppReferenceKind(string projectPath, string name) =>
        DeclaresInFileBasedApp(projectPath, name, ReferenceKind.Sdk) ? ReferenceKind.Sdk : ReferenceKind.Package;

    // Whether a file-based app has a #:package or #:sdk directive (literal or through a #:property) for the name.
    private bool DeclaresInFileBasedApp(string projectPath, string name, ReferenceKind kind) =>
        _fileBasedAppDirectives.PackageVariables(projectPath, kind).ContainsKey(name) ||
        _fileBasedAppDirectives.References(projectPath).Any(reference =>
            reference.Kind == kind && string.Equals(reference.Name, name, StringComparison.OrdinalIgnoreCase));

    private VersionLocation LocateInFileBasedApp(string projectPath, string name, ReferenceKind kind)
    {
        if (_fileBasedAppDirectives.PackageVariables(projectPath, kind).TryGetValue(name, out var variableInfo))
        {
            return new FileBasedVariableVersion(variableInfo);
        }

        if (kind == ReferenceKind.Package)
        {
            // `dotnet add package` would add a #:package directive next to the #:sdk one rather than update it.
            if (DeclaresInFileBasedApp(projectPath, name, ReferenceKind.Sdk) &&
                !DeclaresInFileBasedApp(projectPath, name, ReferenceKind.Package))
            {
                return FileBasedAppNotEditable(
                    projectPath,
                    name,
                    $"The file declares {name} with #:sdk, not #:package; upgrade it as an SDK.");
            }

            // `dotnet add package` rewrites a literal #:package directive.
            return new LiteralVersion();
        }

        var reference = _fileBasedAppDirectives.References(projectPath)
            .FirstOrDefault(reference =>
                reference.Kind == ReferenceKind.Sdk &&
                reference.VariableInfo == null &&
                string.Equals(reference.Name, name, StringComparison.OrdinalIgnoreCase));

        if (reference == null)
        {
            return FileBasedAppNotEditable(
                projectPath,
                name,
                $"Expected a literal #:sdk {name}@<version> directive (id match is case-insensitive; trailing comments are preserved).");
        }

        if (reference.UsesPropertyReferences)
        {
            return FileBasedAppNotEditable(
                projectPath,
                name,
                "Direct #:sdk updates require a literal id@version (for example #:sdk Cake.Sdk@6.0.0); " +
                "property references in the name or version must be changed via #:property lines.");
        }

        return new FileBasedDirectiveVersion(reference);
    }

    private VersionLocation LocateProjectSdk(string projectPath, string name)
    {
        var sdk = ProjectSdkReferenceHelper.Discover(_fileSystem, projectPath)
            .FirstOrDefault(reference => string.Equals(reference.Name, name, StringComparison.OrdinalIgnoreCase));

        return sdk != null
            ? new ProjectSdkVersion(sdk)
            : new NotEditable(
                $"Failed to update the version of SDK '{name}' in '{projectPath}': the project file declares no versioned SDK with that name.");
    }

    private VersionLocation LocatePackage(string projectPath, string name)
    {
        if (!_evaluator.GetVersionVariables(projectPath).TryGetValue(name, out var variableInfo))
        {
            return new LiteralVersion();
        }

        bool dotNetAddCanUpdate =
            variableInfo.ElementType != "GlobalPackageReference" &&
            !variableInfo.IsVersionOverride &&
            !(variableInfo.ElementType == "PackageReference" &&
              !string.Equals(variableInfo.PackageReferenceFilePath, projectPath, StringComparison.OrdinalIgnoreCase));

        if (variableInfo.UnsupportedReason == null)
        {
            return new MSBuildVariableVersion(variableInfo, dotNetAddCanUpdate);
        }

        if (!dotNetAddCanUpdate)
        {
            return new NotEditable(
                $"Could not update '{name}' in '{variableInfo.PackageReferenceFilePath}': {variableInfo.UnsupportedReason}. " +
                "Update the version manually.");
        }

        // Treat it like a literal version: the expression is replaced with the new version.
        return new LiteralVersion(
            $"'{name}' in '{variableInfo.PackageReferenceFilePath}' will be set to a literal version because " +
            $"{variableInfo.UnsupportedReason}; its version expression '{variableInfo.PackageReferenceVersion}' is not preserved.");
    }

    private static NotEditable FileBasedAppNotEditable(string projectPath, string name, string hint) =>
        new($"Failed to update file-based app '{projectPath}' for '{name}'. {hint}");
}

using NuGet.Versioning;

namespace DotNetOutdated.Core
{
    internal static class VersionRangeExtensions
    {
        /// <summary>
        /// Formats a range for writing into a project file. A plain minimum version (<c>[1.2.3, )</c>) is
        /// written exactly as <see cref="NuGetVersion.ToString()"/> would, so existing single-version
        /// upgrades are unchanged; anything else uses NuGet's short range syntax, e.g. <c>[1.2.3, 2.0.0)</c>.
        /// </summary>
        public static string ToVersionString(this VersionRange versionRange) =>
            versionRange.IsPlainVersion()
                ? versionRange.MinVersion!.ToString()
                : versionRange.ToShortString();

        /// <summary>
        /// Whether the range is just a minimum version (<c>[1.2.3, )</c>), i.e. equivalent to a single <see cref="NuGetVersion"/>.
        /// </summary>
        public static bool IsPlainVersion(this VersionRange versionRange) =>
            versionRange is { HasLowerBound: true, IsMinInclusive: true, HasUpperBound: false, IsFloating: false };
    }
}
